import sys
input = sys.stdin.readline

def solve(n, x, gasstations):
    dp = [0] * (x + 1)
    fuel_sum = sum(gasstations)
    for station in gasstations:
        for j in range(x - station + 1, -1, -1):
            dp[j] = min(dp[j], dp[j + station] + fuel_sum)
    return max(0, dp[-1] - fuel_sum)

import itertools

def solve(test_cases):
    moves = [(1, 0), (0, -1)] # (add, subtract)
    results = []
    try:
        for n in test_cases:
            if isinstance(n, int) and 1 <= n <= 1000:
                visited = set()
                stack = [(n, 0, None)]
                while stack:
                    state, count, prev_state = stack.pop()
                    if state in visited:
                        continue
                    visiting = not prev_state
                    if (state % 3 == 0) or (count >= 10 and visiting):
                        results.append("First" if visiting else "Second")
                        continue
                    visited.add(state)
                    states_to_check = [state + x[0] for x in moves if state + x[0] <= 1000 and state + x[0] not in visited or (visited and prev_state is not None and state + x[0] != prev_state)]
                    for state_to_check in states_to_check:
                        stack.append((state_to_check, count+1, state))
                continue
            else:
                raise ValueError(f"Invalid test case {n}")
    except Exception as e:
        print(e)
    return results

