def powers_of_two_and_three():
    powers = [2, 3]
    for i in range(1, 64):
        powers += [pow(p, i) for p in powers]
    return powers

def euler(n):
    powers = powers_of_two_and_three()

    for power in reversed(powers):
        if n < power:
            break

        divisor = n // power
        remainder = n % power

        if remainder == 0:
            return True

        n -= power - remainder

    return False

def can_vanya_win(n):
    return euler(n) or (10 > n)

