def solve(input_string, k):
    """
    Solves the given string with the given 'k'
    """
    if len(input_string) == 0 or k <= 0 or k >= len(input_string):
        return "Invalid input: k must be between 1 and len(string)"

    chars = list(input_string)
    result = []

    for i in range(len(chars)):
        if chars[i] == 'A':
            if (i == len(chars) - 1) or (chars[i+1] != chars[i]):
                result.append((i + 1, 'B'))   # Replace A with B at this index
                break
        elif chars[i] == 'B':
            if k > 0:
                while k > 0 and (i == len(chars) - 1 or chars[i + 1] != chars[i]):
                    result.append((i + 1, 'A'))   # Replace B with A at this index
                    k -= 1
                if k > 0:     # If k is not fully used, replace remaining As to Bs
                    for j in range(len(chars) - i, len(chars)):
                        result.append((j + 1, 'B'))   # Add operations to change the last characters
                else:           # If all k is used and all remaining characters are Bs, no more changes needed
                    break
            else:    # If k == 0 or chars do not contain As anymore
                break

    return '\n'.join([str(i) + ' ' + c for i, c in result])

import functools
import math

def dijkstra(graph, start):
    dist = {node: float('inf') for node in graph}
    prev = {node: None for node in graph}
    dist[start] = 0

    unvisited = set(graph)
    while unvisited:
        current = min(unvisited, key=lambda node: dist[node])
        unvisited.remove(current)

        for neighbor, edge in graph[current].items():
            tentative_dist = dist[current] + edge
            if tentative_dist < dist[neighbor]:
                dist[neighbor] = tentative_dist
                prev[neighbor] = current

    return dist, prev

