import collections

def solve(plays):
    player_count = collections.Counter(plays)
    if max(player_count.values()) == min(player_count.values()):
        return '?'
    elif sum(player_count[b] for b in player_count.keys()) % 2 != len(plays) % 2:
        winning_player = 'A' if max(player_count.values()) > min(player_count.values()) else 'B'
    else:
        winning_player = next((b for b, c in player_count.items() if c != (len(plays)//2)), None)
        if not winning_player:
            return '?'
        else:
            winning_count = [play for play in plays if play == winning_player]
            return 'A' if len(winning_count) > (len(plays) + 1) // 2 else 'B'
    return winning_player

