import functools

def sort_with_twos(arr):
    @functools.lru_cache(None)  # Memoization to avoid recursive overflows
    def sort_util(index, power):
        if index >= len(arr):
            return True

        operations = []
        for m in range(power, -1, -1):
            if (2 ** m) <= index:
                operations.append(-(1 << m))
                arr[index] += sum(operations)
                if sort_util(index + (1 << m), m):
                    return True
                arr[index] -= sum(operations)
        return False

    # Base case for empty array is always sorted
    if len(arr) == 0:
        return True

    return sort_util(0, len(arr))

def solve():
