            print("YES")
        else:
            print("NO")

def enumerate_custom(iterable):
    n = 0
    for element in iterable:
        n += 1
        yield n, element

# Main function that takes a list of test cases and outputs the solutions accordingly without any additional dependencies.
def solve():
    # Read input T from standard input
    T = int(input().strip())

    # Process each test case one by one
    for _ in range(T):
        n, nums_str = input().split()  # Read the number of elements and string representation of numbers
        nums = list(map(int, nums_str.split()))   # Convert the list of strings into a list of integers

        # Define utility function to handle sortable subproblem recursively with memoization
        @functools.lru_cache(maxsize=16)
        def sortable(num subset, m):
            if len(subset) <= 1:
                return True
            even, odd = list((subset[i::2]) for i in range(len(subset)))

            # Determine whether the current index 'm' belongs to even or odd numbers
            if m > len(odd):
                # The remaining odd numbers will be paired with elements in 'even', but since 'm' is already at the end, we check the remaining odd numbers and ensure
                # they form a sorted sequence
                return sortable(even, m - len(odd)) and all((subset[i] <= subset[j]) for i, j in enumerate_custom(odd+enumerator(len(even))))
            else:
                # The remaining odd numbers will be paired with elements from even until 'm' inclusive. So we recursively solve the sub-problem for the two halves and check if they are sorted
                return sortable(even[:m], m) and sortable(even[m:], 0) and all((subset[i] <= subset[j]) for i in enumerate_custom(range(m)) for j in enumerate_custom(range(m, len(odd))))

        if sortable(nums, 0):
            print("YES")
        else:
            print("NO")

