import collections
def solve():
    for _ in range(int(input())):
        n, m = map(int, input().split())
        if not n or not m:
            print("YES" if not n and not m else "NO")
            continue
        s = input()
        t = input()

        # Check if the string 's' is already good
        if all(s[i] != s[i+1] for i in range(n-1)) or not any(s[i] == t[j] for i in range(n) for j in range(m)):
            print("YES")
            continue

        q = collections.deque()
        # Iterate through 's' and check for a possible insertion position
        for i in range(n):
            while q and q[-1] == s[i]:
                q.popleft()
            if not q:
                q.append(s[i])
            # Check if 't' overlaps with the current sequence at index 'i' in string 's'
            if t in q or any(s[i+j] == t[k] for j, k in enumerate(range(min(m, n-i)))):
                break
        else:
            # If a possible insertion position was found, check if we can add 't' without overlapping
            if not any(t[j] == s[i+j] for j in range(min(m, n))):
                print("YES")
            else:
                print("NO")

