def solve(arr):
    # Find the sum of all array elements and check if it is equal to twice the last element or zero
    total_sum = sum(arr) - arr[-1] * 2
    if total_sum == 0 or total_sum == arr[-1] * 2:
        return 'Yes'

    # Initialize an empty set to store distinct pairs of adjacent elements and their sums
    sum_set = {(arr[i], arr[i+1]) + arr[i+1] for i in range(len(arr) - 1)}

    # If there is any pair with the same sum as the last two elements, return "Yes" as the input array is good or can be made good through permutations
    if sum_set & set([c[0] + arr[-1] for c in combinations(arr[:-1], 2)]):
        return 'Yes'

    return 'No'

