import sys

def divisibility_check(n):
    return all([n % i != 0 for i in (3, 2)])

def triplets(n):
    for x in range(1, n//3 + 1):
        y = (n - x) // 2
        z = (x * (x + y)) // y
        if divisibility_check(z) and gcd(y, z) == 1 and (y > z and z < n - y - x):
            return [x, y, z]
    return []

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input().strip())

        if not triplets(n):
            print("NO")
        else:
            triplets_result = triplets(n)
            if triplets_result:
                print("YES")
                print(*triplets_result, sep=' ')

import math
from itertools import combinations

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        count = 0
        while n % i == 0:
            factors.append(i)
            n //= i
        i += 1
    if n > 1:
        factors.append(n)
    return factors

def divide_by_three(factors):
    return [factor for factor in (3 - x) * [factor] if factor % 3 != 0 for x, factor in enumerate(factors)]

def solve(n):
    if 3 in prime_factors(n):
        print("NO")
    else:
        triples = []
        for t in combinations(range(1, int(math.sqrt(n))), 3):
            total = sum(t)
            factors = prime_factors(total - n)
            if not set(divide_by_three(factors)).issubset(t) and total > n:
                triples.append(sorted(t))
        print(*triples or ["NO"], sep=",")

from collections import defaultdict

def sieve_of_eratosthenes(n):
    primes = [True] * (n+1)
    primes[0], primes[1] = False, False
    for p in range(2, int(n**0.5)+1):
        if primes[p]:
            for i in range(p*p, n+1, p):
                primes[i] = False
    return primes

