    primes = sieve_of_eratosthenes(100_001)
    three_multiples = set([3*i for i in range(1, 1+len(primes)) if primes[i]])
    result = defaultdict(lambda: False)

    for candidate in reversed(range(2, int(sqrt(100_001)) + 1)):
        if candidate in primes and candidate not in three_multiples:
            for other in reversed(range(candidate+1, int(sqrt(100_001)) + 1)):
                if other in primes and (other+candidate <= 100_001) and (candidate+other not in three_multiples):
                    target = 100_001 - candidate - other
                    if target < candidate and target in primes and target not in three_multiplies:
                        result[(target, candidate, other)] = True

    for triplet in sorted(result.keys()):
