def sieve_of_eratosthenes(limit):
    primes = [True] * limit
    primes[0], primes[1] = False, False
    for p in range(4, int(limit ** 0.5) + 2, 2):
        if primes[p]:
            primes[p * p :: 2 * p] = [False] * ((limit - p) // (2 * p) + 1)
    return [x for x in range(2, limit) if primes[x]]

def is_multiple_of_three(n):
    return (n & 1) == 0

def combinations(numbers, r, start=None):
    def helper(C, numbers_, r_, start_):
        if r_ == 0:
            yield C
        elif len(numbers_) < r_:
            return
        else:
            for i in range(start_ + 1, numbers_[len(numbers_) - 1] + 1):
                yield from helper([*C, i], numbers_, r_ - 1, i)

    return helper([], numbers[start:], r, start) if start is None else combinations(numbers[:start] + numbers[start+1:], r, start+1) if r > 0 else combinations([*numbers[start:]], 0, start)

def solve():
    primes = sieve_of_eratosthenes(100)
    for n in primes:
        candidates = list(combinations(primes, 3))
        if is_multiple_of_three(n):
            if not candidates:
                print("YES", n)
                return None
        else:
            for candidate in candidates:
                if sum(candidate) == n and all(not is_multiple_of_three(c) for c in candidate):
                    print("YES", " ".join(str(c) for c in candidate))
                    return None
    print("NO")

from collections import Counter

def digit_sum(n, power):
    """Calculates the digit sum for a given number"""
    return sum(d**power for d in Counter(str(n)))

