    y = x
    while True:
        current_digit_sum = digit_sum(y, k) + Counter(str(y))[0] % k
        if current_digit_sum == 0 and all((c * d**k < y for c, d in Counter(str(y)).items())):
            return y
        elif current_digit_sum > 9*k:
            break
        else:
            y += 1
    return None

