def beautiful(k):
    def sum_digits(n):
        return sum(int(i) for i in str(n))

    def is_beautiful(num, k):
        if num < k:
            return False
        elif sum_digits(num) % k != 0:
            return False
        else:
            return True

    last = max([x for x in range(1, 10**9+1) if is_beautiful(x, k)])
    candidate = last + 1

    def find_next_beautiful(num):
        while True:
            nonlocal candidate
            if is_beautiful(candidate, k):
                yield candidate
                candidate += 1
            else:
                candidate += 1

    return list(find_next_beautiful(last))[0]

