def kth_beautiful(k: int):
    beautiful = {0: 1} if k == 2 else {}
    counter = count(1)

    for num in accumulate(chain([0], beautiful.keys()), lambda x, y: y + (x+1)):
        if digit_sum(num) < k or k not in {2}:
