def queue_simulation(pin):
    queue = list(pin)  # create a copy of the pin as we modify it along the process
    positions = [[1]]     # starts at position 1 (where the cursor is initially)
    steps = []           # to keep track of the number of steps required at each digit position

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # possible movements: left, right, up, down

    while positions:
        pos = positions.pop()
        step_count = 0
        current = queue[pos]

        for direction in directions:
            next_pos = [(pos[0] + d) % len(queue), pos[1]]
            if queue[next_pos[1]] == str(current).swapcase():
                steps.append(step_count + 1)
                positions.append(next_pos)
                break

        if not steps:
            steps.append(float('inf'))

    return max(steps)

