def solve(n, m, x, s):
    # Initialize set to store already visited strings
    seen = set()
    q = deque([(x, 1)])
    seen.add((x, 1))

    while q:
        curr_str, dist = q.popleft()

        if len(curr_str) == m:
            # If we have reached the desired length, check if it matches s
            if curr_str == s:
                return dist

        for i in range(1, min(len(curr_str), 2 * (m - dist)) + 1):
            append_count = min(i, len(curr_str) - dist + 1)
            append_string = curr_str[-append_count:]

            new_str = curr_str + (append_string * i)

            if new_str not in seen:
                q.append((new_str, dist + i))
                seen.add(new_str)

    # Return -1 if there is no solution found
    return -1

