def solve(n, strengths, endurances):
    if n == 1:
        return max(strengths) if strengths[0] > 1 else -1

    max_hp = max(endurances)
    priority_queue = [(h, i) for i, h in enumerate(reversed(strengths)) if h > 1]
    heappush(priority_queue, (max_hp + 1, 0))

    while len(priority_queue) and priority_queue[0][0] >= max_hp:
        weight, index = heappop(priority_queue)
        if index == 0:
            break

        strength = strengths[index]
        endurance = endurances[index]
        weights_to_check = [weight - x for x in range(1, min(strength + 1, weight))]
        for w in weights_to_check:
            if not priority_queue or w >= priority_queue[0][0]:
                heappush(priority_queue, (w, index))

    return max_hp * (1 if len(priority_queue) == 0 else -1)

