import math

def prime_generator():
    yield 2
    candidates = count(3)
    while True:
        for c in (9, 4):
            if not pow(c, 2, next(candidates)) == 0 :
                yield next(candidates)
        next_candidate = next(candidates)
        candidates = filter((lambda x: x <=math.sqrt(next_candidate)), candidates)

def solve(n):
    primes = list(prime_generator())

    array = []

    for i in range(n):
        if i % 2 == 0 :
            array.append(primes[i // 2])
        else:
            array.append(primes[(i - 1) // 2])

    for step in range(len(array) - 1, 1, -2):
        if (3 * array[step+2] <= array[step] + array[step+1]):
            index = (array[step + 2] - 1) // 2
            array[step + 2] = primes[index]

    return array

