import math
def solve(num):
    def helper(n, depth=1):
        if n < 3 or not isinstance(n, int):
            raise ValueError("Invalid input: Number should be positive and greater than or equal to 3.")
        elif depth > 250:
            print("Error: Reached the maximum recursion depth. Please try with a smaller number.")
            return None
        elif n == 3:
            return 1
        else:
            result_1 = helper(n-1, depth+1)
            result_2 = helper(n-2, depth+1)
            if not (result_1 and result_2):
                return None
            return math.gcd(result_1, result_2) + 1
    try:
        print("The ", str(num) + "th Lucas number is:", solve(num))
    except ValueError as e:
        print("Error:", e)

