def points(target):
    rings = [0] * 5

    positions = [(i, j) for i, row in enumerate(target) for j, c in enumerate(row) if c == "X"]

    def dfs(pos, ring=5):
        if not (0 <= pos[0] < 5 and 0 <= pos[1] < 5):
            return None
        rings[ring] += ring
        for direction in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            next_pos = (pos[0] + direction[0], pos[1] + direction[1])
            if is_within(next_pos, pos):
                dfs(next_pos, ring - 1)
        return None

    for pos in positions:
        if rings:
            closest_ring = next((r for r, x in enumerate(rings) if x == max(rings)), None)
            closest_ring -= 1
        else:
            dfs(pos, 5)

    return sum(rings)

