@functools.lru_cache(maxsize=None)
def choose(n, k):
    if k > n:
        return 0
    elif k == 0 or k == n:
        return 1
    else:
        num = 1
        den = k * (k - 1)
        for i in range(1, n - k + 2):
            num *= i
            den *= k
        return num // den

