def increasing_decreasing(sum_, arr):
    increment = [a[1] - a[0] for a in zip(arr, arr[1:])]
    decrement = [b[1] - b[0] for b in zip(increment, increment[1:])]

    if not all(decrease <= 0 for decrease in decrement) or not sum_ == sum(arr):
        return False

    return True

