import re

def solve(n, a, data):
    online = sets = deque([set() for _ in range(a)])
    subscribers = set(range(1, n + 1))

    for char in re.findall('([+-])', data):
        if char == '+':
            sets.rotate(-1).append(subscribers - sets[-1])
        else:
            sets.pop()

    online_after = set.union(*sets)
    result = "NO" if len(online_after) < n else (
        "MAYBE" if len(online_after) != n else "YES"
    )
    print(result)

