    for idx, value in enumerate(cumsum):
        if value > cumsum[n - 1]:
            max_len = len(dropwhile(lambda x: not x == value or x > value, b[idx:]))
            end_idx = idx + max_len
    m = min(2 * (end_idx + 1) if end_idx else n, n * 2)
    subsequences = []
    def _find_sequence(left, right):
        if left > right:
            return None
        mid = (left + right) // 2
        cmp = b[mid]
        left_subseq = _find_sequence(left, mid - 1)
        right_subseq = _find_sequence(mid + 1, right)
        if left_subseq and right_subseq:
            return list(chain([b[mid]], sorted(list(chain(left_subseq, right_subseq)))))
        elif left_subseq:
            return left_subseq
        elif right_subseq:
            return right_subseq
        else:
