from collections import defaultdict

def solve(t):
    for _ in range(t):
        n, m = map(int, input().split())
        if (n * m) % 2 == 1: # check if number of elements is odd
            print("NO")
            continue

        carpet = [input() for _ in range(n)]

        # create adjacency list to check connectivity
        adj_list = defaultdict(list)
        for i in range(m):
            for j, c in enumerate(carpet):
                if c[i] == 'v' or c[i] == 'V':
                    adj_list['v'].append((j+1, 'vi', '#k'))
                if c[i] == 'i' or c[i] == 'I':
                    adj_list['i'].append((j+1, 'ka', '#a'))
                if c[i] == 'k' or c[i] == 'K':
                    adj_list['k'].append((j+1, 'vi', '#v'))
                if c[i] == 'a' or c[i] == 'A':
                    adj_list['a'].append((j+1, None  , '#i', 'k'))

        # initialize empty stack and visited lists
        stack = [None] * (n * m)
        visited = [False] * (n * m)

        def dfs(node):
            if node is None:
                return False

            nonlocal visited, stack
            visited[node - 1] = True
            stack[node - 1] = 'visited'
            connected_nodes = adj_list[chr(ord('A') + node % 26)][node - 1]

            for n in reversed(connected_nodes):
                if not visited[n[1] - 1]:
                    ret = dfs(n[1])
                    if ret:
                        return True

                    # cycle detected, return False
                    if n[3] and stack[n[1] - 1] == 'visited':
                        return False

            stack[node - 1] = 'stacked'
            return True

        if all(map(eval, ['stack[{} - 1]'.format(x) for x in range(1, n * m + 1)))): # check if length of stack is equal to number of elements after traversal
            print("YES")
        else:
            print("NO")

