def solve(t):
    def is_prime(num):
        if num <= 3:
            return num > 1
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def generate_sequences():
        sequences = []
        for i in range(1, 10):
            base = list('123456789'[:i] + '9' * (10 - i) + list('123456789')[i:])
            sequences += [base]
        return sequences

    sequences = generate_sequences()
    for seq in sequences:
        # Simulate deletions of digits
        for j in range(10):
            if len(seq) < 3 or gcd(int(''.join(seq)), 1) > 1 or not is_prime(sum(map(int, seq))):
                continue
            seq.remove(str(j))
        # Pruning duplicate sequences and finding prime ones
        primesequences = []
        for seq in set(frozenset(sorted(seq)) for seq in itertools.permutations(*[(sorted(list(map(int, s))) for s in sequences]) if sum(s) % 2 == 1)):
            if all([abs(i - j) != 1 or i > j for i, j in enumerate(sequence=seq)]):
                primesequences.append(seq)
        for prime_sequence in primesequences:
            primenum = int(''.join(prime_sequence))
            if primenum > 4 and is_prime(primenum):
                return '.'.join(map(str, sort(prime_sequence)))
    return '-1'

