import re

def solve():
    t = int(input())
    for _ in range(t):
        line = input()
        sequences = [re.split('', line)]  # divide a string into substrings of the given repeated pattern (single characters)
        removed_digits = []

        while len(sequences) > 1:
            curr = list(sequences)
            for digit in range(1, 10):
                if digit not in ''.join(curr):  # checking if any sequence contains the current digit
                    break
                for seq in curr:
                    new_seq = seq.replace(str(digit), '', 1)
                    if new_seq == '':  # skipping empty strings as they're not considered valid sequences
                        continue
                    if new_seq not in sequences:
                        sequences.append(new_seq)
            removed_digits.append(None)
            min_len = min(len(s) for s in sequences)  # finding the minimum sequence length to filter invalid sequences
            sequences = [seq for seq in sequences if len(seq) == min_len]  # keeping only sequences with the same minimum length

        if not sequences:
            print(-1)
        else:
            sequence = sequences[0]
            number = ''.join(sequence)  # joining the sequences together into a single string
            if isprime(int(number)):
                print(number)

