        for num in map(int, f):
            if len(num_str := str(num)) == 2: continue  # Case of only two digits: not considered impossible but composite by default
            deletions = set(combinations(sorted(num_str), len(set(num_str))))
            results = []
            for deletion in deletions:
                deleted = [int(ch) for ch in list(num_str) if ch not in deletion]
                factors_of_remaining = set([factors(reduce(lambda a, b: a*b, deleted))])
                if len(deleted) and not set(list(filter(lambda f: f[0] <= 1 or (len(num_str) - len(f[1])) < f[0], factors_of_remaining))) and len(factors_of_remaining) > 2:
                    results.append(''.join([str(d) for d in deleted]))
            if results:
                print(*results, sep='\n')
                break

def is_prime(n):
    if n <= 1: return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def sieveOfEratosthenes(limit):
    primes = [True] * limit
    primes[0] = primes[1] = False
    for num in range(2, int(limit ** 0.5) + 1):
        if primes[num]:
            for multiple in range(num*num, limit, num):
                primes[multiple] = False
    return [num for num in range(2, limit) if primes[num]]

