                    if (num2 <= len(available_elems)) and (len(c_group) + num2 - 1 < len(available_elems)):
                        assigned = [available_elem for available_elem in (range(min(num2,len(available_elems)), max(0, len(available_elems)-num2+1))) if available_elem not in c_group]
                        multiples = {j * num2 for j in range(1, min((len(c_group) + num2 - 1),num2))}
