from collections import defaultdict

def solve(a, b, c):
    n = a + b + c
    memo = {}

    def dfs(i, player):
        if i > n:
            return True
        if i in memo:
            return memo[i]

        if player == 'A':
            for j in range(1, a+1):
                if dfs(i + j, 'K'):
                    memo[i] = True
                    return True
        else:
            for j in range(1, c+1):
                if dfs(i + j, 'A'):
                    memo[i] = False
                    return False

        memo[i] = None
        return False

    answer = ''
    if a > b:
        answer = ('First' if dfs(0,'A') else 'Second')
    elif a < b:
        answer = ('First' if dfs(0,"K") else 'Second')
    else:
        answer = ('First' if any([dfs(i, 'A') for i in range(c + 1)]) else 'Second')

    return answer

import sys
from collections import defaultdict
from functools import lru_cache

@lru_cache(maxsize=None)  # cache size unlimited for this scenario
def can_Anna_move(buttons):
    return buttons.keys() <= {i for i in range(1, len(buttons) + 1)}

@lru_cache(maxsize=None)
def can_Katie_move(buttons):
    next_player = (2 if can_Anna_move(buttons) else 1)
    return buttons.keys() <= {i for i in range(next_player, len(buttons) + 1)}

@lru_cache(maxsize=None)
def is_tie(buttons):
    for player in range(1, 4):
        if can_Anna_move(buttons) and can_Katie_move(buttons):
            return True
        buttons[player] = {i: True for i in range(player * (player == 2), len(buttons) + 1)}
    return False

def solve():
    if is_tie({1: defaultdict(bool, {'A': True}), 2: defaultdict(bool)}) or not can_Anna_move({1: defaultdict(bool, {'A': True}), 2: defaultdict(bool)}):
        return "Second"
    else:
        return "First"

import functools

def gcd(a, b):
    """Calculate the Greatest Common Divisor (GCD) of two numbers."""
    return functools.reduce(lambda x, y: x if not y else gcd(y, x % y), (max(a,b), min(a,b)))

def solve(arr):
    """Determine whether the given array can be colored with equal sum parity."""
    odd_count, even_count = 0, 0
    for num in arr:
        if num % 2 == 1:
            odd_count += 1
        else:
            even_count += 1
    return True if (odd_count > 0 and even_count > 0) else False

