from collections import deque

def solve():
    test_cases = int(input())
    for _ in range(test_cases):
        n = int(input().strip())
        a = list(map(int, input().split()))
        max_heap = [-i for i in a]
        operations = 0

        queue = deque()

        while max_heap or queue:
            if not max_heap:
                break
            for i in range(n):
                if queue and a[queue[-1][1]] > max_heap[0]:
                    a[queue.pop()[1]] = -max_heap.pop() + 1
                    operations += 1

            while max_heap:
