                if any([a[i] > popped for i, v in enumerate(queue) if v >= 0]):
                    break

        print(operations)

def has_connections(graph, node):
    visited = [False] * len(graph)
    stack = [[node]]
    while stack:
        current = stack.pop()
        for neighbor in graph[current[0]]:
            if not visited[neighbor]:
                visited[neighbor] = True
                if neighbor == node:
                    return True
                stack.append([neighbor])
    return False

def generate_graph(a, b):
    n = len(a)
    graph = [[] for _ in range(n)]
    for i in range(n - 1):
        if a[i] == a[i + 1] or (b[i] != b[i + 1] and b[i] % 2 == b[i + 1] % 2):
            graph[i].append(i + 1)
            graph[i + 1].append(i)
    return graph

def has_all_connections(a, b):
    n = len(a)
    if all([has_connections([[0] + a[:i]], a[i]) for i in range(1, n)) and \
          all([has_connections([b[i], 0] + b[i+1:], b[-1]) for i in range(n - 1, -1, -1)):
        return True
    return False

def find_swaps(a, b):
    if len(set(a) & set(b)):
        raise ValueError("Students cannot match twice.")
    graph = generate_graph(a, b)
    missing_connections = 0
    for i in range(1, len(a)):
        if not has_connections(graph, a[i]):
            missing_connections += 1
    return missing_connections // 2

def solve(a, b):
    if not has_all_connections(a, b):
        swaps = find_swaps(a, b)
        return [{f'swap_{i+1}': a[i], f'swap_{i+2}': b[i]} for i in range(swaps)]
    else:
        return []

