        if i >= len(arr):
            return 0
        if arr[i] % 2 == 0:
            count = 0
            for j in range(i+1, min(2*i, len(arr))):
                if arr[j] % 2 == 0 and arr[j]:
                    count += 1
                    arr[j] = 0
                    break
            return count + count_swaps(i+1)
        else:
            count = 0
            for j in range(i+1, min(2*i, len(arr))):
                if arr[j] % 2 != 0 and arr[j]:
                    count += 1
                    arr[j] = 0
                    break
            return count + count_swaps(i+1)

    even_count, odd_count = sum([1 for num in arr if num % 2 == 0]), sum([1 for num in arr if num % 2 != 0])
    return "YES" if count_swaps(0) >= len(arr)-min(even_count, odd_count) else "NO"

