def solve(input_list, k):
    # Create priority queue (heapq) for sorting escalator steps based on their height.
    heapq = deque()

    vlad_height = input_list[0]  # Starting height of Vlad.

    for step in input_list:
        # Add step to the heapq if its height is greater than or equal to Vlad's current height and less than his height + k (step space).
        if step >= vlad_height and step < vlad_height + k:
            heapq.append(step)

