def can_converse(h, step):
    return (h > step) or ((step - h) < step - (max([-1] + list(range(len(h))))))

def find_steps():
    steps = accumulate([1], lambda x, y: x + y)
    max_stairs = max([-1] + list(range(len(steps))))

    max_passenger_height = steps[-1] - max_stairs + 1 if max_stairs < len(steps) else -1

    return [step for step in range(len(steps)) if can_converse(steps[step], max_passenger_height)]

def solve(n, m, k, H, passengers_heights):
    steps = find_steps()

    passengers_can_converse = [False] * n

    for i in range(len(passengers_heights)):
        passengers_can_converse[i] = any([steps[j] == i or can_converse(passengers_heights[i], steps[j]) for j in enumerate(passengers_heights) if i != j and (None, None)[1] <= j[1] < len(passengers_heights)])

    return sum(passengers_can_converse)

