import sys

def get_test_cases(numTestCases):
    testCases = []
    for _ in range(numTestCases):
        testsValues = list(map(int, sys.argv[2 + (3 * (_ + 1)):]))
        num, power, base = testsValues[:]
        testCases.append((num, power, base))
