def solve(num, power, base):
    availableSet = {i for i in range(Num + 1)}
    powerset = set([pow(base, j) for j in range(power + 1)])
    countableSubset = [pow(base, i) for i in sorted(powerset & availableSet)]

    if num < sum(countableSubset):
        return False

    countablesubsets_len = len(countableSubset) if countableSubset else 0
    comb_list = [(subset, len(subset)) for subset in combinations(countableSubset, r=num - sum(countableSubset) - countablesubsets_len)]

    if not comb_list:
        return False

    possibleSolutionIndices = [i for i, tuple in enumerate(comb_list) if all([j < k for (j, k) in zip(*tuple))]

    if not possibleSolutionIndices:
        return False

    return bool(possibleSolutionIndices)

