def extended_gcd(a, b):
    if b == 0:
        return (1, 0, a)
    else:
        x1, x2, y1, y2 = extended_gcd(b, a % b)
        return (y2, x2 - (a // b) * y2, x1), b

def smallest_positive(a, b):
    gcd_val, _, _ = extended_gcd(a, b)
    if gcd_val > 1:
        return None
    else:
        return math.floor((b - a + 1) / gcd_val)

