import math

def digits_queue(n):
    return list(str(n))[::-1] + [0]*(2 - len(list(str(n))))

def level_sums(n):
    dq = digits_queue(n)
    for i in range(1, 32):  # Change this number for handling larger or smaller numbers
        x = int(''.join([str(dq[0])]+ ['0' for _ in range(i-1)])) * (2**(i-1)) + int(''.join([str(dq[1])] if dq[1].isdigit() else '0') * (2**(31-i)))
        yield x

def level_sum(n):
    levels = [0]*(int(math.log(n, 2)) + 1) # Handles numbers up to $10^{64}$ (1024 bits) without overflow issues. Adjust range at top of file as needed for larger/smaller numbers.
    for x in level_sums(n):
        levels[x>>1] += 1 << (x&1) # Assigning bits to positions based on LSB and taking into account powers of 2
    return sum([int(''.join(reversed(str(i)))) for i in levels])

