            current_sum = sum((-a[i] if b else a[i]) for i, (b) in enumerate(positions)) # Adapt the current_sum based on the selected positions
            max_sum, min_ops = max(max_sum, current_sum), min(min_ops, num_ops + 1 if current_sum > 0 else num_ops)
        else:
            dfs(positions + [1 if pos[i] == 0 else 0], current_sum + (0 if pos[i] == 0 else a[i]), num_ops)
            dfs(positions + [0 if pos[i] == 1 else 1], current_sum - (0 if pos[i] == 1 else a[i]), num_ops) # Optimization: Negate the sum calculation to avoid multiplication

    # Process input and output results in separate functions for improved code structuring
    def read_input():
        n = int(input())
        return [int(x) for x in input().split()]  # Assumes input format: Number of elements, followed by space-separated integers. Returns a list of integers.

    def write_output(mx, mn):
