        if mn == float('inf'):
            print("INF")
        else:
            print(mn)

    a = read_input()  # Update variable name for clarity
    solve(a)  # Call the 'solve' function directly with input processed from user's input
    write_output(mx, mn)  # Output final result to user

def solve(arr):
    @functools.lru_cache(maxsize=16)
    def f(ix):
        return sum(arr[ix:]) if ix >= len(arr) else 0, arr[ix].count(-1) if ix < len(arr) else 0

    pos = float('inf')
    neg = float('inf')
    res_sum = 0
    res_ops = len(arr)

    for i in range(len(arr)):
        curr_sum, curr_ops = f(i)
        if curr_sum < pos:
            pos = curr_sum
            if not (curr_ops == neg and res_sum > curr_sum + 1): # Ensure previous result is only subtracted in case it can be improved
                res_sum = curr_sum + 1
                res_ops = curr_ops
        elif curr_sum > pos and curr_ops < neg:
            pos = float('inf')
            neg = curr_ops
    return res_sum, res_ops

def solve(n, arr):
    costs = {}
    dp = [[0] * 52 for _ in range(n)]

    for num in arr:
        if num not in costs:
            costs[num] = []
        costs[num].append(len(arr) - 1)

        # Fill dp[] from right to left
        for j in range(51, -1, -1):
            if j <= num:
                dp[len(arr) - 1][j] = max(dp[len(arr) - 1][j], dp[-1][j])
                if costs[j]:
                    last_index = costs[j][-1] - 1

                    if last_index >= 0 and dp[last_index][j] > dp[len(arr) - 1][j]:
                        dp[len(arr) - 1][j] += max(costs[j])

            else:
                dp[len(arr) - 1][j] = dp[-1][j]
                if j < min_value:
                    min_value = j

        for i in range( len(arr)-1, 0, -1):
            dp[i-1][:] = dp[i][:]

    max_cost = float('-inf')
    for i in range(52):
        if i in costs:
            max_cost = max(max_cost, dp[-1][i])

    print(max_cost)

from functools import lru_cache

def solve(arr):
    if not arr:
        return 0

    @lru_cache(maxsize=None)
    def cost(i, c):
        if i == len(arr):
            return 0

        j_min = min(arr[i])
        j_max = max(arr[i])

        q = ((1 << j_max) - (1 << j_min)) & c  # get the bit-value of the range [j_min, j_max] from c
        if not q:
            return cost(i + 1, c | (1 << i)) + arr[i]   # color current element with new color
        else:
            return cost(i + 1, c)                      # element is already colored with a suitable color

    return cost(0, 0)

def game(a, b):
    @lru_cache(maxsize=None)  # maximum cache size allowed in specific environment
    def solve(n, k):
        if n == 0 or k == len(a) + len(b):  # Check edge cases for no more monsters left and empty lists case
            return 0
        elif k > len(a):   # For the sake of simplicity, this code considers Tenzing can only move the last available monster and not in the middle
            return solve(n, k-1)
        else:
            ability_diff = a[n-1] - b[k-1]  # Update abilities after a move
            if ability_diff <= 0 and solve(n-1, k) >= 0:  # If Tsondu survives his turn and the difference is negative or equal to zero, Tenzing loses
                return 1
            elif ability_diff > 0 and solve(n, k - 1) < 0 and (solve(n, k - 2) >= 0 if k != len(a) else None): # If Tsondu eliminates both monsters on his turn or Tenzing cannot play a valid move
                return -1
            elif ability_diff > 0:   # When two monsters have the same power, they remain as is
                return solve(n, k-1)
        return 0    # The game ends as a draw when neither player can make moves to win

    return "Tsondu" if solve(len(a), len(b)) > 0 else ("Tenzing" if solve(len(a), len(b)) == 0) or "Draw"

