        tsondu_abilities = abilities[1:]
        trenzing_abilities = [abilities[0]] + abilities[2:]

        tsondu_heap = ((float("inf"), 0),)  # empty min-heap for Tsondu's monsters
        trenzing_heap = ([-float("inf"), -1],)   # empty max-heap for Trenzing's monsters

        while tsondu_heap and trenzing_heap:
            tsondu_action, tsondu_index = heappop(tsondu_heap)
            trenzing_action, trenzing_index = heappop(trenzing_heap)

            if tsondu_abilities[tsondu_index] > trenzing_abilities[trenzing_index]:
                tsondu_abilities[tsondu_index] -= trenzing_abilities[trenzing_index]

                if tsondu_abilities[tsondu_index] <= 0:
                    continue   # mark Tsondu's monster as dead and skip it in future iterations

                heappush(tsondu_heap, (-tsondu_abilities[tsondu_index], tsondu_index))

            else:
                trenzing_abilities[trenzing_index] -= tsondu_actions[tsondu_index]

                if trenzing_abilities[trenzing_index] <= 0:
                    continue   # mark Trenzing's monster as dead and skip it in future iterations

                heappush(trenzing_heap, (trenzing_abilities[trenzing_index], trenzing_index))

        if sum([monster_ability for monster_ability in tsondu_abilities if monster_ability > 0]) > 0:
            print("Tsondu")

        elif sum([monster_ability for monster_ability in trenzing_abilities if monster_ability > 0]) > 0:
            print("Trenzing")

