def solve(n, memo={}):
    if n in memo:
        return memo[n]
    if n == 1 or (n % 2 == 0 and n > 1):
        memo[n] = 'Bob'
    elif n % 3 == 0:
        x, i = n // 3, 1
        while True:
            test_value = (x * 3 + i) % n
            if not test_value or test_value >= (n - 2):
                break
            i += 1

            if solve(n - test_value, memo) == 'Alice':
                memo[n] = 'Alice'
                return memo[n]
    memo[n] = 'Bob'
    return memo[n]

from collections import defaultdict

def solve(n):
    visited = defaultdict(lambda: False)

    def helper(remaining_tiles):
        if remaining_tiles == 0:
            return True

        for i in range(1, remaining_tiles + 1):
            current_count = remaining_tiles - i
            if visited[(remaining_tiles - i)] and current_count in [i, remaining_tiles - i]:
                return True

            if current_count > 0 and not visited[current_count]:
                visited[current_count] = True
                if helper(current_count):
                    return True
                visited[current_count] = False

        return False

    visited.clear()
    visited[n] = True
    return helper(n)

