def gcd(a, b):
    # Euclidean Algorithm to find greatest common divisor (gcd) between two integers
    if b == 0: return a
    return gcd(b, a % b)

def extGCD(a, b):
    if a == 0: return (b, 1, 0)
    r1 = a % b
    (q, r2) = divmod(a // b, 1)
    while r1:
        (r1, (r2, r3)) = (b % r1, (r1 % b, r2))
        a, b = b, r1
    return (a, r2, r3)

def solve(nums):
    # Find a unique common divisor for the differences between each pair of numbers in the given list
    common_divisors = []
    for i in range(1, len(nums)):
        for j in range(i+1, len(nums)):
            diff = abs(nums[i] - nums[j])
            CD = None
            for possible_CD in common_divisors:
                if possible_CD > (diff):
                    break
                if possible_CD % diff == 0 or diff % possible_CD == 0:
                    CD = possible_CD
            if not CD:
                CD, remainder = gcd(diff, max(common_divisors)) if common_divisors else diff
                common_divisors.append(CD)

    # Use the Extended Euclidean Algorithm to find integer multiples x and y that satisfy x*n + y = n (where n is the sum of all numbers in the input list) with gcd(n,z)=1
    _, inv_n, _ = extGCD(sum(nums), len(nums))
    x = int(inv_n * (len(nums) - 1)) if isNegativeInteger(x) else (x % len(nums))
    return nums[x]

