    for line in lines:
        if len(line) > 1 and sum(line) != ((len(line) * (len(line) - 1)) // 2):
            return "NO"

    # Create a hashmap to store the number of robots and their counts.
    count_robots = {robot: 0 for robot in range(max(lines, key=sum)+1)}

    # Update the count of each robot in each line according to their positions.
    for line in lines:
        for i in range(len(line)):
            if line[i] != 0:
                count_robots[line[i]] += 1

    # If all counts are equal to 0 or 1, then the arrangement is possible.
    for count in count_robots.values():
        if count > 1:
            return "NO"

    # Generate all permutations and check if any permutation forms a valid solution. This will be done because there might exist more than one valid permutation depending on the problem constraints.
    perms = list(itertools.permutations([list(line) for line in lines]))

    for perm in perms:
        robots_count = {}  # Count number of each robot in the current permutation
        for i, line in enumerate(perm):
            cur_robot = next((key for key, value in count_robots.items() if value), None)  # If there is no value for current robot, we move on to the next line.
            if cur_robot:
                robots_count[cur_robot] = 1 + robots_count.get(cur_robot, 0) if cur_robot in robots_count else 1
                for j, num in enumerate(line):
                    if num == cur_robot:
                        # If the current robot is placed at a position where it wasn't supposed to be (according to its report), it doesn't form a valid solution.
