def write_output(output):
    """Function to write output."""
    print('\n'.join(map(lambda x: str(x).upper(), output)))

def is_valid_permutation(robot_numbers):
    """Function to check if a permutation is valid."""
    valid = [True] * len(robot_numbers)
    for i, (idx, num) in enumerate(sorted(robot_numbers, reverse=True)):
        if not valid[idx-1]:
            continue
        if i == idx - 1:
            continue
        if num != valid[i]:
            return False
        valid[idx] = False
    return True

def find_solution(robot_numbers):
    """Function to find solution."""
    solutions = []

    for i in range(1, len(robot_numbers) + 1):
        permutations = combinations(range(1, 1+len(robot_numbers)), i)
        for p in permutations:
            if is_valid_permutation([[robot_numbers[j][0], len(p)] for j in p]):
                solutions.append(' '.join(['{}{}'.format(str(x)[1], str(y)[-2:-1]) for x, y in sorted(p, reverse=True)])
    return list(set(solutions)) if solutions else []

def solve():
    """Function to start solving."""
    n, lines = read_input()
    robot_numbers = [[int(x), int(y)] for x, y in lines]
    output = find_solution(robot_numbers)
    write_output([f'Case #x: y' if idx + 1 <= len(output) else 'Case #x: Impossible' if idx + 1 <= n else 'Done.' for idx, line in enumerate(lines)] + output)

