def solve(n, a):
    # First check if all numbers in a have positive parity or are zeros. If not, return "NO".
    if any(x % 2 != 0 and x > 0 for x in a) or any(x < 1 for x in a):
        return "NO"

    # Calculate the max difference to create a beautiful array.
    max_num = max(a)
    max_diff = math.ceil(math.sqrt(max_num)) - 1

    # Check each pair of numbers and ensure the differences are valid. If not, return "NO".
    for i in range(len(a)):
        for j in range(i + 1, len(a)):
            if abs(a[i] - a[j]) > max_diff:
                return "NO"

    # If no invalid differences were found, create the beautiful array and return "YES".
    beautiful_array = [0] * n
    for num in a:
        index = num % 2
        if index == 0:
            while num > 1:
                num -= 2
                beautiful_array[num] = beautiful_array[num] + 1 if num < len(beautiful_array) else num
        else:
            beautiful_array[num - 1] += 1
    return "YES"

from functools import lru_cache

def has_same_parity(numbers):
    return numbers[0] % 2 == (numbers[1:%len(numbers)] % 2).__xor__() if len(numbers) > 1 else True

@lru_cache(maxsize=None)
def can_build_beautiful_array(numbers, i=0):
    # Base case: When the number of elements is 1, it's possible to build a beautiful array with just that element.
    if len(numbers) == 1:
        return True

    # Recursive cases: Consider all remaining elements and subarrays obtained by removing smaller indexed elements.
    for j in range(i+1, len(numbers)):
        # Checks whether the rest of the subarray also maintains the same parity.
        if has_same_parity(numbers[j:]):
            subarray = numbers[:j]
            updated_numbers = list(reversed(subarray))
            # Skip the checked elements to avoid duplicating previous cases during recursive calls or when generating the final beautiful array.
            result = can_build_beautiful_array(updated_numbers, j)
            if result:
                return True
    return False

