                        if i < k and j >= i and j < k and input_str[j] == input_str[k]:
                            g[(j,i)] = [] # remove previous assignment (if it exists), to mark as unconnected node and start DFS at this node
                            g[(i,j)] = [(i,j)]  # add new entry for forward edge from i to j
                elif ((i+k) & 1 == 1 and input_str[i] != input_str[k]):
                    idxs = []
                    for j in range(n):
                        if j < i or j > k: continue #skip non relevant indices (less than i or greater than k)
                        if input_str[j] == input_str[i]:
                            g[(j,k)].append((j,k))  # add reverse edge from j to k if they share the same symbol
                            idxs += [(j,True)]  # mark that index as connected to i and k
                        elif input_str[j] == input_str[k]:
                            g[(i,j)].append((i,j)) # add forward edge from i to j if they share the same symbol
                            idxs += [(j,False)]  # mark index as connected only to i or k (not both)

                    for j,flag in idxs:
                        if flag:
                            g[(i,k)].append((i,j)) # add forward edge from i to j through k
                            g[(k,j)][-1] = (k,i)  # update reverse edge at j from k to i
                        else:
                            g[(i,k)].append((j,k)) # add forward edge from j through i to k
                            g[(k,j)][-1] = (i,k)  # update reverse edge at j from k to i

        for m in g.values():
            m[:] = sorted(m, key=lambda x:x[1])   # sorting by end index, so that we visit higher indices before lower ones, since it's a DFS approach

        stack, vvisited = [(0,0)], set() # initializing the data structure for DFS. note that we start with ((0,0), {}), but unpacking it to be more readable
        while stack:
            (nidx, idx1) = stack[-1]   # get index of the current node nidx from top of the stack. idx1 is the end index of the current melody we are considering
            if nidx >= len(input_str): continue  # if this node has already been visited, pop it and move to next melody in dfs stack
            if (nidx+idx1) & 1 == 0:      # check if the next index is odd since we only need to process even indices when traversing the graph
                idx2 = nidx + idx1 // 2
                if g[(nidx,idx2)]:     # checking for the existence of a forward edge connected i (nidx) with j (idx2)
                    newStack = sorted(g[(nidx,idx2)])      # sort edges by end index, so that we visit higher indices before lower ones
                    stack[-1] = (newStack[-1][0], idx1 + g[(nidx,idx2)][-1][1])  # setting current melody end index as the end index of new melody in stack
                    for edge in newStack:
