import itertools

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def extended_euclidean(a, b):
    if a == 0:
        return (0, 1) if b > 0 else (1, 0)
    (s0, s1), (x0, x1) = extended_euclidean(b % a, a)
    return (s1 - (b // a) * s0, x1 - (b // a) * x0), (s0, x0))

def solve(a):
    g = gcd(*map(operator.sub, a))
    mx = sum(a) - g * (len(a) - 1)
    sx, sy = extended_euclidean(mx + g, len(a))
    b = list(itertools.accumulate(map(lambda x: x + sx // len(a) * g, a)))
    for i in range(1, len(b)):
        b[i] += sy * (i - 1) * g
    return sorted(list(set(b)))

