def find_path(graph, start, goal):
    discovered = set()
    queue = [(start, [], 0)]
    while queue:
        node, path, length = queue.pop(0)
        discovered.add(node)

        if node == goal:
            return length

        for neighbor in graph[node]['neighbors']:
            if neighbor not in discovered:
                new_path = list(path + [neighbor])
                queue.append((neighbor, new_path, length + graph[neighbor]['skills'][0]))
    return None

def min_time_to_get_all_skills(graph, books):
    start_node = sorted(graph.nodes())[0]
    possible_root_paths = [find_path(graph, start_node, skill) for skill in graph.nodes()]

    if not any(possible_root_paths):
        return -1

    min_time = float('inf')
    for root_cost in possible_root_paths:
        if root_cost is None:
            continue
        total_time = root_cost + find_path(graph, skill, start_node)  # second call to find_path assumes a single path from skill to start_node
        min_time = min(min_time, total_time) if total_time is not None else min_time
    return min_time

