    comb_gcd = reduce((lambda a, b: a*b), comb)
    result = gcd(comb_gcd, n) == n
    return result if result else False

def find_solution(n):
    factors = sorted(set(range(1, n+1)))
    factor_combs = [c for c in itertools.combinations(factors, len(factors)) if is_valid_combination(c, n)]

    def find_perfect_array(factor_comb):
        result = []
        for i, f in enumerate(factor_comb):
            power = 0
            for j, fact in enumerate(factors):
                if fact == f:
                    power = j + 1
                    break
            result += [f ** power] * power
        return list(reversed(result))

    solution = find_perfect_array(factor_combs[0]) if factor_combs else []
    return solution, factor_combs

