def solve(template):
    # A generator that yields all combinations of digits (not question marks) in the given string.
    def recurse(remaining, choices=[1, 2, 3, 4, 5, 6, 7, 8, 9], pos=0):
        if len(remaining) == 0:
            yield "".join([str(n) for n in choices])    # Yield current string after recursion completes
        elif pos > len(remaining):
            return                                    # Return at end of possible positions without needing to recurse further

        current = choices.pop(0)                      # Grab the first digit from the choices and remove it from consideration
        for _ in range(current):
            yield from recurse(remaining, choices=[n for n in choices if n > current], pos=pos + 1)     # Recurse with updated choice set
        choices.insert(0, current)                    # Reset the first digit option so we can move on to other higher digits

    results = [i for i in recurse(template)]            # Generate all possible combinations from the template
    return list(filter(lambda x: not re.match(r'^[0]*$', x), results))   # Filter out any single-integer strings or empty strings

