            opinions_member[i+1] = int(opinion == '+') - 1   # Convert + to 1 and - to 0, subtract 1 to account for input format (1 means disagree)
        opinions.append(opinions_member)

    for opinion_index in range(1, len(members[0]) + 1):
        y, n = 0, 0
        for member in opinions:
            if member[opinion_index] == -1:
                y += 1
            else:
                n += 1

        if y + n > max(y,n):
            # Expel disagreeing people (Y)
            to_expel = [i for i, opinions_member in enumerate(opinions) if any(opinions_member[-1] == -1)]
            for member_to_expel in to_expel:
                opinions.pop(member_to_expel)
                if len(opinions) < n:   # If all members were expelled before the last discussion, break the loop
                    break

    return sum([len(member) for member in opinions]) + 1

