import collections

def solve(n, k):
    table = [list(map("+-", input())) for _ in range(n)]

    agreement_counts = collections.Counter(map(lambda x: x[0], table))
    disagreement_counts = dict((d, c) for d, c in agreement_counts.items() if d != '+')
    majority_opinion = max(agreement_counts)

    if sum(disagreement_counts[d] for d in disagreement_counts.values()) < agreement_counts[majority_opinion]:
        return n - sum([disagreement_counts[d] for d in disagreement_counts]) + 1
    else:
        expelled = 0
        for opinion, count in agreement_counts.items():
            if opinion != majority_opinion or count < disagreement_counts[opinion]:
                continue
            expelled += min(count - disagreement_counts[opinion], expelled)
        return n - expelled + 1

import itertools

def is_valid(point):
    x, y = point
    return 0 <= x < 1 and 0 <= y < 1

def distance(p1, p2):
    return ((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2) ** 0.5

def manhattan_distance((x1, y1), (x2, y2)):
    return abs(x1 - x2) + abs(y1 - y2)

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

def solve():
    # Read initial input from the console
    q = int(input().split()[0])

    points = [list(map(float, input().strip('[]').strip('(),'))) for _ in range(q)]

    for i, (a, b) in enumerate(points):
        p_visited = set()  # Set of visited Points
        queue = [[Point(0, 0), Point(a, b)]]  # Initialize queue with Ian and Mary

        def dfs(current_point):
            if len(queue) == 0 or current_point in p_visited:
                return None

            nonlocal queue
            point = queue.pop()
            p_visited.add(tuple(point))

            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                new_point = Point(point.x + dx, point.y + dy)
                if is_valid(new_point) and manhattan_distance((a, b), new_point) <= 1:
                    queue.append(new_point)

            return dfs(min(queue, key=lambda p: (a - p.x) ** 2 + (b - p.y) ** 2))

        path = []
        while True:
            step = dfs(Point(0, 0))
            if step is not None:
                path.append(step)
            elif queue:
                path += queue[:]
                break

        if len(path) == 1:
            print("1")
            print(*[(int(x), int(y)) for x, y in [(0, 0)] + path])
        else:
            k = min([distance((0, 0), p) for p in path[:-1]], default=float('inf'))
            optimal_path = [p for p in path if distance((0, 0), p) == k]
            if len(optimal_path) > 2:
                print("Error: More than one optimal solution exists!")
            else:
                print(*[(int(x), int(y)) for x, y in [(0, 0)] + list(itertools.chain(*[path for _, path in enumerate(optimal_path) if len(path) <= 2]))])

