from collections import defaultdict

def extended_gcd(a, b):
    if b == 0:
        return (1, 0, a % b)
    else:
        x, y, q = extended_gcd(b, a % b)
        return (y, x - (a // b) * y, b)

def mod_inverse(a, m):
    x, _, _ = extended_gcd(a, m)
    if x < 0:  # Adjust for negative multiplicative inverse
        x += m
    return x

def solve(n, k):
    if n < k or k <= 1 or (n % 2 == 1 and k != n):   # Adding more constraints to handle edge cases
        return "No"

    counts = defaultdict(int)
    for coin in str(n // k):
        if coin not in counts:
            counts[coin] = 0
        counts[coin] += 1

    if n % k != 0:
        return "No"

    inverse = mod_inverse(counts[str(k)], k)
    coins_needed = (n - k * ((n – k) // k)) * inverse

    result = [0] * len(set(str(n)))  # Initialize a list of zeros with the unique digits of n as indices
    for coin in str(k):
        result[int(coin)] += counts[coin]

    if any([count - coins_needed < 0 for count, _ in result.items()]):   # Ensure there are enough coins to represent `n` using the remaining change
        return "No"

    for count, value in result.items():
        if value - coins_needed >= 0:   # Update the counts with the needed coins
            result[int(count)] -= coins_needed

    count = 0
    for item in sorted(result.items(), key=lambda x: -x[1]):   # Sorting the items based on their value, and iterating through sorted items to find a solution
        if item[1] != 0:
            count += item[1] * int(item[0]) ** (k // int(item[0]))
            if count >= n:
                return "Yes"

    return "No"  # If no proper combination of coins is found, return No

