def group(collection, n):
    return [collection[i:i + n] for i in range(0, len(collection), n)]

def contains_sequence(seq, sub_seq):
    return all(item != sub_seq or item < sub_seq[0] for item in seq[:-len(sub_seq)]) and sum(sub_seq) == sum(seq)-sum(seq[:-len(sub_seq)])

def extend(seq, n=2):
    if not seq:
        return False

    candidates = [seq[i:i + n] for i in range(len(seq) - n)]

    if n == 2 and contains_sequence(seq, (1, 1)):
        return True, seq

    new_candidates = []
    for candidate in candidates:
        extension = extend(group(candidate, n-1), n-1)
        if extension[0]:
            return True, extension[1] + candidate

        new_candidate = extend(seq[:len(candidate) + 1], n)
        if new_candidate[0]:
            return True, new_candidate[1][-len(candidate):] + candidate

    return False, None

