import math

def manhattan_distance(a, b, c, d):
    return abs(c - a) + abs(d - b)

def diagonal_steps_required(a, b, c, d):
    if abs(c - a) != abs(b - d):
        return math.inf
    else:
        midpoint = ((a + c) // 2 , (b + d) // 2)
        diagonal_distance = manhattan_distance(*midpoint)
        x_diff, y_diff = abs(c - a), abs(d - b)
        steps = diagonal_distance * 2
        half_steps = int(min(x_diff, y_diff)) / 2 if x_diff > y_diff else steps // 2
        return steps + 2*half_steps

