        return ''.join(sorted(s)) < ''.join(lex_smaller_char(s))

    class SortUtil:
        @staticmethod
        def lex_smaller_char(s):
            stack = []
            for c in s:
                while stack and stack[-1] > c:
                    stack.pop()
                stack.append(c)
            return ''.join(reversed(stack))

