    idx_min_char = bisect_left('acgt' + s, s[0])

    for c in 'acgt'[idx_min_char:]:
        if lex_smaller(s + c):
            break

    result = list(s)
    result[0], result[idx_min_char] = result[idx_min_char], result[0]
    print("".join(result))

