def manhattan_distance(position1, position2):
    return abs(position1[0] - position2[0]) + abs(position1[1] - position2[1])

def solve(board, initial_pos, dest_pos):
    # BFS queue uses a list of lists where each sublist represents a node with two elements: distance and position
    queue = [[manhattan_distance(initial_pos, initial_pos), initial_pos]]

    visited = [[]] * len(board) * len(board[0])  # visited[y][x] tracks if positions in the grid have been processed
                                                # visited is a list of lists where each sublist represents a row of the grid

    while queue:
        _, p = heapq.heappop(queue)
        x, y = p
        if (x == dest_pos[0] and y == dest_pos[1]):  # check if current position is the destination
            return p[0]
        visited[y][x] = True                       # mark current position as processed in the grid

        for direction, step_x, step_y in ((0, 1, 0), (0, -1, 0), (1, 0, 0), (-1, 0, 0)):
            new_pos = [(y + (step_y * n) % len(board), x + (step_x * n) % len(board[0])) for n in range(p[0] + 1)]
            if all((new_pos_[0], new_pos_[1]) not in visited) and any([manhattan_distance(dest_pos, np) <= p[0] + 1 for np in new_pos]):
                heapq.heappush(queue, [p[0] + 1, np])

    return -1  # return -1 if no solution found

