def solve(n, m, actions):
    recent_actions = list(range(1, n + 1)) # Initialize empty Recent Actions field
    result = [0] * n # Initialize an array of zeros for the final result

    timestamp = 1 # Start from timestamp 1

    for action in actions:
        if action <= n:
            action_index = recent_actions.index(action)
        else:
            action_index = -1  # Action is on a post outside of the Recent Actions field, update its corresponding index in the result array by subtracting the size of Recent Actions (n) from the action ID to get an index within the result array and adjust it accordingly.
        if action_index >= 0:
            result[action_index] = timestamp
        recent_actions[0] = action # Update the first element in the heap with the new action (placing it at the top of Recent Actions)
        heapq.heappop(recent_actions)       # Remove the smallest item from the bottom of the heap (the current head, not relevant anymore since we have a new action at the beginning). If the new action is outside Recent Actions, nothing happens here.
        timestamp += 1

    return result

