def solve(input_str, actions):
    recent_actions = deque(list(range(1, len(actions) + 1)))
    timestamps = [-1] * len(actions)
    timestamp = 0

    for action in actions:
        if 0 <= action < len(recent_actions):
            recent_actions[action], recent_actions[0] = recent_actions[0], recent_actions[action]
            heapq.heappop(recent_actions)

        if recent_actions:
            timestamp = max(timestamps) + 1
            if timestamp < action:
                timestamps[recent_actions[0]] = timestamp
            elif timestamp == -1:
                break

    return ",\n".join(map(str, timestamps))

