import sys
from collections import defaultdict

def create_neighbor_graph(matrix):
    """Initializes a neighbor graph, where each cell's neighbors are adjacent cells."""
    graph = {}
    for i, row in enumerate(matrix):
        for j, element in enumerate(row):
            if matrix[i][j] == '#':
                continue
            up, down, left, right = (i - 1, i + 1, j - 1, j + 1)
            graph[(i, j)] = {(up, down, left, right)} \
                if all(0 <= k < len(matrix)) and matrix[k] else set()
    return graph

def dfs(graph, parent, connected_component):
    """Performs Depth-First Search (DFS) on the given graph."""
    size, visited = 1, set()
    unconnected_components = defaultdict(set)

    def aux_dfs(node):
        if node in visited:
            return False

        visited.add(node)
        connected_component.add((parent[node], node))

        connected_and_unconnected = graph[node] - visited

        if len(connected_and_unconnected) > 0:
            for neighbor in connected_and_unconnected:
                aux_dfs(neighbor)

        unconnected_components[size].update((parent[k], k)
                                            for k in graph[node] - visited if k not in visited)

        return True if len(graph[node]) == size else False

    # Perform the actual DFS traversal and gather connected components information
    for node, _ in graph.items():
        if aux_dfs((0, 0), (node)):
            size += 1
            unconnected_components[-size] = {k[::-1] for k in unconnected_components[size]}
            del unconnected_components[size]

    return connected_component | unconnected_components.values()

def bfs(graph, start):
    """Performs Breadth-First Search (BFS) on the given graph."""
    visited, queue = set(), [start]
    component = set((0, start))

    while len(queue) > 0:
        node = queue.pop(0)
        for neighbor in graph[node]:
            if neighbor in visited:
                continue
            visited.add(neighbor)
            parent[(neighbor)] = node
            component.add((parent[neighbor], neighbor))
            queue.append(neighbor)

    return component

def solve(x1, y1, x2, y2):
    """Finds the minimum number of obstacles needed to block the path between two coordinates."""
    graph = create_neighbor_graph([
        ['.'] + row + ['.' for row in input()]
    ])
    connected_components = dfs(graph, parent={(0, 0): (0, 0)})

    BFS_result = bfs(graph, (x1, y1))

    # If the start cell is not part of the same connected component as the end cell
    if x1 == x2 and y1 == y2:
        return 0

    obstacles = 0
    for c in BFS_result:
        if (x2, y2) in c and len(c) - 1 > 0:
            obstacles += 1

    # If the start and end cells belong to different connected components
    if (x2, y2) not in BFS_result:
        connected_component = next((comp for comp in connected_components
                                   if (x2, y2) in comp), None)
        if connected_component is None:  # If the end cell belongs to an unconnected component
            unconnected_component = [comp for comp in connected_components
                                if len(comp) > 0 and (x2, y2) not in comp][0]
            obstacles += len(unconnected_component) - 1
        else:
            # If no path exists between the two connected components that contain the start and end cells
            for parent_size, component in enumerate(connected_components.values(), 0):
                if (x2, y2) not in component and len(component) > 1:
                    obstacles += len(unconnected_components[parent_size + 1])

    return -1 if obstacles == 0 else obstacles

