from collections import Counter
from functools import reduce

def solve(n, strings):
    char_freqs = Counter(''.join(strings)) | Counter(range(1, n+1))  # Calculate the frequency of each character based on given strings and characters up to n
    freqs = reduce((lambda x, y: x + y), list(char_freqs.values()))  # Sum up total frequencies from character count dictionary
    left, right_symmetry = [], []
    for char in range(1, n+1):
        if char in char_freqs:
            left.append(char_freqs[char] // freqs)
            right_symmetry.append(char_freqs[chr(2 * char)] // freqs)  # Symmetrical count for characters larger than n is preserved and divided by total frequency to align with others
        else:
            left.append(0)
            right_symmetry.append(right_symmetry[-1] if len(left) > 1 else 0)  # Set counts for missing characters based on their nearest-odd neighbours (preserving symmetry)
    return 'YES' if all(x == y for x, y in zip(left, right_symmetry)) else ('NO' if any(x != y for x, y in zip(left, right_symmetry)) else '?')

