def solve(final_string):
    if final_string[0] == '1':
        return len(final_string) * 2 - 1
    elif final_string[0] == "0": # Edge case: if the string starts with an empty sequence or exactly one zero (e.g., '1', '01')
        return 1 + len(final_string) // 2 * 2 # If zero, prepend the missing zeros and append double length of ones at the end
    else:                         # All other cases
        for i in range(len(final_string)):
            if final_string[i] == '1':
                return len(final_string) - i

def solve():
    test_cases = int(input())

    while test_cases > 0:
        n = input()

        zeroes, ones = [], []
        if len(n) == 0:
            print("0\n")
            test_cases -= 1
            continue

        # Process the given string
        for char in n:
            if char == '1':
                ones.append(char)
            elif char == '0':
                zeroes.append(char)

        # Perform operations from both ends based on their counts
        while len(ones) < len(zeroes):
            zeroes.insert(0, '0')
            ones.insert(0, '1')

        while len(zeroes) > len(ones):
            zeroes.append('0')
            ones.append('1')

        # Print the answer in reverse order
        for char in reversed((ones + zeroes)):
            print(char, end="")
        print("\n", end="")

        test_cases -= 1

from collections import deque

def solve(n):
    q = deque(''.join(['1'] * (n // 2) + ['0'] * (n // 2))[::-1]) if n % 2 else deque(''.join(['0'] * (n // 2) + ['1'] * (n // 2)))
    cnt_zero = 0

    while q or len(q) <= n:
        if not q:
            q.appendleft('0')
            cnt_zero += 1
        else:
            back, front = q.popleft(), q[-1]
            if back != front:
                cnt_zero += 1
            q.append(back ^ front)
    return len(q) + cnt_zero

