def manhattan_distance((x1, y1), (x2, y2)):
    return abs(x1 - x2) + abs(y1 - y2)

def is_valid_input(input):
    try:
        num = int(input)
        return True
    except ValueError:
        return False

def solve():
    test_cases = None

    while not is_valid_input(test_cases):
        test_cases = input("Enter the number of test cases: ")

    for _ in range(int(test_cases)):
        n = int(input())
        moves = input()
        pos = [0, 0]  # Alperen's current position
        candy = [1, 1]  # candy coordinates
        stack = [pos]

        def dfs(cur):
            nonlocal stack
            if len(stack) == 0:
                return
            cur_idx = stack.index(cur)

            if manhattan_distance((cur[0], cur[1]), candy) <= 1:
                print("YES")
                del stack[cur_idx+1:]
                return

            for move in moves:
                next_pos = list(cur)
                if move == 'U':
                    next_pos[1] += 1
                elif move == 'D':
                    next_pos[1] -= 1
                elif move == 'L':
                    next_pos[0] -= 1
                elif move == 'R':
                    next_pos[0] += 1
                stack.append(next_pos)

            dfs(next_pos)

        dfs(pos)
        if len(stack) > 0:
            print("NO")

import collections

def solve(tests):
    # Read testcases from file, where each has 3 lines: Testcase count on first line, string moves in second line, and third line is empty/optional
    input_file = open("input.txt", "r").read().strip()
    tests = [list(map(str.split, input_file.split('\n'))) if '\n\n' in input_file else [[test] for test in input_file.split('\n')]]

    for test in tests:
        n = int(test[0])
        path = list(test[1])
        dx = [0, 1, 0, -1]
        dy = [1, 0, -1, 0]
        visited = {(0, 0)}
        q = collections.deque([(0, 0)])

        while q:
            x, y = q.popleft()
            for i in range(4):
                nx, ny = x + dx[i] * (2*y - n+1), y + dy[i] * (2*x - n+1)
                if 0 <= nx < n and 0 <= ny < n and (nx,ny) != (1,1) and (nx,ny) not in visited:
                    q.append((nx, ny))
                    visited.add((nx, ny))

        print("YES" if (1, 1) in visited else "NO")

import itertools

def move_to(position, moves):
    directions = {'U': (0, 1), 'D': (0, -1), 'L': (-1, 0), 'R': (1, 0)}
    new_position = position[0] + sum([directions[m][0] for m in moves if m in directions])
    new_row = position[1] + sum([directions[m][1] for m in moves if m in directions])
    return (new_row, new_position)

