import itertools

def solve(n, s, r):
    # Generate all possibilities
    candidates = [i for i in range(1, 7)] * n
    perm = list(itertools.permutations(candidates))
    solutions = []

    # Filter out invalid sequences
    for p in perm:
        total = sum(p)
        if total != s:
            continue

        max_num, min_num = max(p), min(p)
        if max_num > min_num and max_num - min_num == len(p) - 1:
            remaining_sum = total - (max_num + r)
            if remaining_sum in [i for i in range(s-r+1, s)]:
                solutions.append(list(p))
    if len(solutions) == 1:
        print(*solutions[0])
    elif solutions:
        print("Multiple Solutions")

