        input_char = yields from iterate(read_integer, lambda x: (x == -1) or (x != -1 and binary_string.append(str(x).strip() if isinstance(x, int) else ''))):

        if not input_char:
            break

    binary_string = [int(c) for c in binary_string]
    reversed_binary_string = reverse(binary_string)

    def is_palindrome(lst):
        if len(lst) == 0 or len(lst) == 1:
            return True
        i = 0
        j = len(lst) - 1
        while i < j:
            if lst[i] != lst[j]:
                return False
            i += 1
            j -= 1
        return True

    if is_palindrome(binary_string) or is_palindrome(reversed_binary_string):
        print("Test Case {}: Yes".format(test_case_number))
    else:
        print("Test Case {}: No".format(test_case_number))

