import math
from mpmath import *

def solve(n):
    for x in range(1, n+1):
        with mp.with_prec(100):  # Uses high-precision floating point numbers for better accuracy near edges
            y = int((mp.log(n - (x ** x), x) if x != x or n - (x**x) > 0 else None).item())  # Logarithm is now done using mpmath for more accurate results
        if y and (y**x * x + y * y**x == n):
            return x, y
    return -1

def solve(n):
    cards = [0] + (list(range(1, n * 2 + 1)) if n & 1 else list(range(n * 2, 0, -2)))
    alice_white, bob_white = 0, 0
    alice_black, bob_black = 0, 0

    for card in cards:
        if card % 2 == 1:
            alice_white += 1
            if alice_white > card:
                alice_black += (card - alice_white)
                break
            alice_black += card // 2
        else:
            bob_white += 1
            if bob_white > card:
                bob_black += (card - bob_white)
                break
            bob_black += card // 2

    return alice_white, alice_black, bob_white, bob_black

from collections import defaultdict, deque

def solve(n: int) -> tuple[int, int]:
    alice, bob = 0, 0
    deck = deque([1 for _ in range(n)])

    while deck:
        length = len(deck)
        if length % 2 == 0:
            dealer = "Alice"
        else:
            dealer = "Bob"

        if length <= len(deck):
            amount = (length - 1) // 2 + 1
        else:
            amount = length // 2

        cards_to_distribute = min(amount, len(deck))

        alice += cards_to_distribute
        bob += cards_to_distribute

        for _ in range(cards_to_distribute):
            deck.popleft()

    return alice, bob

