        w, d, h, a, b, f, g = map(int, input().split())
        if (w == d and (a != f)) or (w != d and abs(a - f) == abs(b - g)):  # Edge case checks for vertical lines parallel to each other
            cable_length = max([h + w, h + d])  # Return the maximum between length for floor and ceiling edges based on whether laptop is left or right of the projector
        elif a == f:  # Special case when they are in the same horizontal line
            if b > g:
                cable_length = d + (b - g)  # Increase by the vertical distance between points for floor edge
            else:
                cable_length = h + (g - b)  # Increase by the vertical distance between points for ceiling edge
        else:
            cable_length = max([h+(w if (a+b) < w else abs(w-a - (f if (f + g > w) or a == f else w - f))),
                               d+(w if (a+b) < d else abs(d-b - (g if (f+g<d) or b==g else g - f))])  # General calculation for non-vertical lines
        print(cable_length)

