import sys
import copy
from collections import deque

def adjacent_possible(node):
    if node == 0:
        return [1]
    elif node == len(_graph) - 1:
        return [node - 1]
    else:
        return [node - 1, node + 1]

def solve():
    initial_state = input().strip().split()
    states = {initial_state: {"visited": False}}  # initial state hashmap with boolean property to mark visited nodes and multiple connections to explore efficiently

    while True:
        for state in list(states.keys()):
            if not states[state]["visited"]:
                graph = copy.deepcopy(_graph)
                for i in graph[state]:
                    neighbours_to_visit = adjacent_possible(i)  # get possible neighbours from state

                    for n in neighbours_to_visit:
                        if n not in graph[state] and n < len(_graph):  # avoid redundant exploration of explored nodes or invalid index errors
                            if n >= 0 and n not in states.keys():  # ensure that we do not explore visited nodes
                                graph[n] = [i]
                                new_state = ''.join([str(x) for x in graph[n]])
                                states[new_state] = {"visited": False}

                # check if this new state solves the puzzle
                if all([graph[i][0] == '1' for i in range(len(_graph))]):
                    print('Yes')
                    sys.exit()

                states[state]["visited"] = True  # mark current state as visited to avoid repeatedly exploring it

        # check if all possible nodes have been explored and the puzzle remains unsolved
        if not any(v['visited'] is False for v in states.values()):
            print('No')
            sys.exit()

