        return "NO" if times[0] % 120 != 0 else "YES"

    # find the end of the last valid time
    prev_end = math.floor((times[-1] + 1) / 120) * 120
    times = sorted(times)

    # iterate through all times and check for any gaps shorter than 120 minutes
    for i in range(len(times)):
        if i == 0:
            start = max(prev_end, times[i] - 120)
        else:
            if (times[i] - times[i-1]) < 120:
                return "YES"
            start = max(prev_end, times[i] - 120)
        prev_end = min(prev_end, times[i]) if prev_end > start else start

    # check if the end of the last valid time is still greater than 0
    return "YES" if prev_end >= 0 else "NO"

