import collections

def solve(n):
    messages = sorted([int(x) for x in input().split()])
    if n <= 1 or all(messages[i + 1] - messages[i] > 120 for i in range(n - 1)):
        return "NO"

    window = collections.deque([None])
    non_overlapping_walks = 0

    for message in messages:
        while window and window[-1][0] < message - 60:
            non_overlapping_walks += (window[-1][0] + 120) // 120
            window.pop()

        if window and message >= window[-1][-1]:
            window[-1][1] += 1
        else:
            window.append([message, 1])

    return "YES" if non_overlapping_walks >= 2 else "NO"

