import sys

def solve(a):
    n = len(a)
    sign = ['+'] * (n - 1)
    min_val, max_val = float('inf'), -float('inf')

    possible_combinations = list(enumerate(sign))

    for index, sign in possible_combinations:
        if index > 0 and sign[index - 1] == sign[index]:
            continue
        tmp = a[0]
        for i in range(1, n):
            if sign[i - 1] == '+':
                tmp += a[i]
            elif sign[i - 1] == '-':
                tmp -= a[i]
        tmp_abs = abs(tmp)
        min_val = min(min_val, tmp_abs)
        max_val = max(max_val, tmp_abs)

    if (n - 1) - possible_combinations.count((1, '+')) == 1:
        min_val = max(min_val, max_val)

    answer = ['+'] * (n - 1)
    for i in range(len(possible_combinations)):
        if possible_combinations[i][1] == '+':
            answer[i] = '-'
    return reduce(lambda x, y: x + ' ' + y, answer)

