        signed = list(map(lambda x: -1 if x < 0 else 1, arr))
        running_total = list(accumulate(signed))
        return min(running_total)

    n = len(a)
    signed_a = [int(x) for x in ' '.join([str(-1), a, str(1)]).split()]
    difference = min_absolute_difference(signed_a)

