def max_xor_diff(a):
    dp = [0] * 64  # initialize dynamic programming array with zeros
    for i in range(len(a)):
        dp[63] = a[i] ^ (dp[63] if i > 1 else 0)   # set the initial max xor value at bit 63
        for k in range(62, -1, -1):
            for j in range(i-1, -1, -1):
                dp[k] = max(dp[k], (1 << (k + 1)) & a[i] ^ dp[k] | (1 << (k + 1)) & a[j] ^ dp[k])
    return max([dp[0][0], dp[0][-1]]) - min([dp[-1][0], dp[-1][-1]])   # get the final result by taking the difference between max and min values from the dynamic programming array

