    for i in range(n):
        for j in range(i + 1, n):
            # Swap bits at positions i and j for each pair of numbers
            arr[i], arr[j] = (arr[i] ^ (1 << j)) | ((arr[j] & ~(1 << j)) << j), (arr[j] ^ (1 << i)) | ((arr[i] & ~(1 << i)) << i)

    return [bin(num)[2:].zfill(n) for num in arr]

def solve(arr):
    evens = [i for i in arr if i % 2 == 0]
    oddevens = [(x, x >> 1) for x in arr if x % 2 != 0]

    dp = [[float('inf')] * (len(evens)+1) for _ in range(len(oddevens))] # Dynamic Programming table

    for j in range(len(dp)):
        odd_val, val = oddevens[j]
        if dp[j][0] == float('inf'):
            dp[j][0] = 0  # Special Case: If only one even value

        else:
            for k in range(len(evens)+1):
                dp[j][k] = min(dp[j][k], 1 + dp[j-1][max(k - odd_val, 0)]) # Using dynamic programming to minimize operations required

    return min(dp[-1])

