import sys

def group_by_length(lst):
    groups = defaultdict(list)
    for el in lst:
        groups[len(el)].append(el)
    return groups

def generate_combinations(groups, n):
    result = []
    def recurse(remaining, combo):
        if len(remaining) == 0:
            result.append(tuple(combo))
        else:
            size = min([len(r) for r in remaining])
            for i, g in enumerate(groups[size]):
                new_remaining = [r[1:] for r in remaining if len(r) > size]
                c = (g + combo[-i-1])[:]
                recurse(new_remaining, c)
    recurse([group for group in groups if len(group) > 0], [])
    return result

