        groups_suffixes = group_by_length([sorted(comb)[::-1] for comb in combinations(lst[-a:], b)])

        matched = generate_combinations(groups_prefixes, len(lst))
        for m in matched:
            for s in groups_suffixes[b]:
                if s == tuple(reversed(m)):
                    print("Yes")
                    break
        else:
            print("No")

from functools import total_ordered

class MyInt(total_ordered):
    def __init__(self, value) -> None:
        self.value = int(value)

    def __lt__(self, other: 'MyInt') -> bool:
        return self.value < other.value

    def __le__(self, other: 'MyInt') -> bool:
        return self.value <= other.value

    def __eq__(self, other: 'MyInt') -> bool:
        return self.value == other.value

    def __ne__(self, other: 'MyInt') -> bool:
        return self.value != other.value

    def __gt__(self, other: 'MyInt') -> bool:
        return self.value > other.value

