from collections import Counter

def solve(s):
    count = Counter(s)
    odd = {}
    even = {}

    for k, v in count.items():
        if v % 2 != 0:
            if k not in odd:
                odd[k] = v // 2 + 1
            else:
                odd[k] = min(odd[k], v // 2 + 1)
        else:
            if k not in even:
                even[k] = v // 2
            else:
                even[k] = min(even[k], v // 2)

    palindrome = ""
    for char in sorted(odd.keys()):
        palindrome += (char * odd[char] + char) * 2
    if even:
        palindrome += "".join(map((lambda x : x * even[x]), even))
    return palindrome[::-1]

