from collections import Counter, deque

def solve(s):
    count = Counter(s)
    q = deque([(k, v) for k, v in count.items()])
    palindrome = []

    while q:
        front, back = q.popleft(), q.pop()
        if front[0] == back[0]:
            times = min(front[1], back[1])
            palindrome += (times * front[0])[:2] + palindrome[-times:][::-1]
            front, back = front[0], back[0] if front[1] != back[1] else None
        else:
            half_len = len(palindrome) // 2
            extra = (front[1] - back[1]) // 2
            palindrome += (half_len * front[0] + half_len * back[0])[:extra * 2]

    return ''.join(palindrome)

import sys
from functools import lru_cache

@lru_cache(maxsize=1000)
def dp(k):
    if k <= 2:
        return k

    res = float('-inf')
    for i in range(2, min(k, n - (k % 2)) + 1):
        res = max(res, dp(k - i) + dp(i))
    return res

def solve(n):
    if n == 2:
        return [1, 2]

    # Fill the array with inf initially. Res is used to store the minimum value possible at that position.
    res = [[float('inf')] * n for _ in range(dp(n))]

    # Initialize both i and k at first element
    i, k = 0, 1
    while True:
        res[k - i][k] = dp(k - i) + dp(i)
        if k == n - 1:
            break
        i += 1
        if i >= n:
            i = 1
            k += 1

    return [res[x][y] for y in range(n-1, -1, -1) for x in range(y+1, n)]

