        dialog = list(map(str, input().strip().split()))  # handling potential trailing spaces when splitting the input
        stack = deque([dialog[0]])
        answered = 0

        for message in dialog[1:]:
            if message == 'Q':
                # when encountering multiple subsequent questions
                while stack and stack[-1] != 'A':
                    stack.pop()  # clear the deque without throwing away customer questions
                if len(stack) > answered:
                    answered += len(stack)
                    stack.clear()
                stack.append(message)
            else:
                stack.append(message)

        if not stack or all([stack[-1] == 'A' for _ in range(answered)]):  # checking consistency when answering questions and clearing the queue
            print("Yes")
        else:
            print("No")

