def sort_check(n):
    total = sum((i * (i + 1)) // 2 for i in range(1, n+1))
    visited = set()
    counter = collections.defaultdict(int)

    def calculate_sum(index):
        if index <= 0:
            return 0
        current = counter[index]
        counter[index] -= 1
        if not counter[index]:
            visited.add(index)
        return current + calculate_sum(index - 1)

    index = n # start from the end
    while index:
        cur_val = counter[index] + 1
        target = total - sum((i * (i + 1) // 2 if i not in visited else 0) for i in range(1, index))
        if cur_val > target:
            return False # cannot be sorted
        counter[index] = cur_val - 1
        index -= 1
    return True # can be sorted

