from itertools import product

def validate_board(n, positions):
    valid = set()
    for position in positions:
        if (position in valid) or ((position[0], position[1]) in valid):
            return False
        if not any((abs(i - position[0]) == abs(j - position[1]) for i, j in positions if (i, j) != position)):
            valid.add(position)
    return True

def is_valid_move(n, positions, start, end):
    for position in positions:
        if ((start[0] == position[0]) or (start[1] == position[1])) and ((end[0] == position[0]) or (end[1] == position[1])):
            continue
        if (abs(position[0] - start[0]) <= n and abs(position[1] - start[1]) <= n) and (abs(position[0] - end[0]) <= n and abs(position[1] - end[1]) <= n):
            return False
    return True

