            input_positions.append(position)

        if not validate_board(n, input_positions):
            print("NO")
        else:
            for position in input_positions:
                for new_position in product(range(1, n + 1), repeat=2) if (position != new_position or is_valid_move(n, input_positions, position, new_position)):
                    index = input_positions.index(position)
                    del input_positions[index]
                    break
            print("YES" if not input_positions else "NO")

