def solve(arr):
    # Store all possible group sums that are either 0 or have positive and negative values.
    groups = set([0])
    for i in range(1, len(arr) + 1):
        partial_sums = {-x: True for x in range(1, i+1) if sum([groups[g] == g[i%2] for g in enumerate(groups, 1)]) == 0 and i % 2 != (groups[-1] if groups else 0)}
        groups |= {x for x in partial_sums.keys() if abs(x) <= sum(arr) // 2}

    # Find all possible divisons of the array into two groups that satisfy group sum conditions using dynamic programming approach
    max_diff = 0
    for group1_size, group2_size in product(groups, repeat=2):
        if group1_size + group2_size != len(arr):
            continue

        group1, group2 = [0]*group1_size, [0] * group2_size
        remaining_arr = arr[:len(arr)]

        for i in range(min(group1_size, len(remaining_arr))):
            while remaining_arr and (remaining_arr[0] != group1[-1] if group1[-1] else group2[-1]):
                remaining_arr.pop(0)
            tmp = remaining_arr.pop(0)

            if not group1:
                group1[-1] = tmp
            elif tmp == group1[-1]:
                continue
            else:
                group2[-1] = tmp

        diff = abs(sum(group1) - sum(group2))
        max_diff = max(max_diff, diff)

    return max_diff

