def factorial(n):
    return math.factorial(n) if n>0 else 1

def solve(n):
    def is_permutation(perm):
        subsegments = []
        for start in range(len(perm)):
            end = perm.index(perm[start], start) + 1
            subsegments.append(perm[start:end])
        return all(sorted(e) == e for e in subsegments)

    perms = [p for p in permutations(range(1, n+1)) if is_permutation(p)]
    min_val = min([len([p for p in perms if is_permutation(p)])])
    return [next((p for p in perms if len(p) == n), range(1, n+1))] * min_val

from collections import Counter as count
def solve(numbers):
    forbidden = [int(n) for n in numbers[1:]]
    valid_combinations = (set(range(10)) - set(forbidden))

    result = sum(count(n).get(n, 0) * len(valid_combinations) for n in range(10))
    if forbidden:
        reduced = {i: c*len(valid_combinations - set([i])) for i,c in enumerate(forbidden)}
        result -= sum(reduced[n] * count(n).get(n, 0) for n in range(10))
    return result

