import sys

def int_or_exit(prompt, default=None):
    while True:
        try:
            return int(input(prompt))
        except ValueError:
            print("Incorrect input! Please enter an integer. ")
    return default

def check_permutation(perm):
    if len(perm) != len(set(perm)):
        return False
    for i, p in enumerate(perm):
        if p == i or p < 0:
            return False
    return True

def find_funny_permutations(n):
    perm = [i for i in range(n)]
    for i in range(2, n + 1):
        for j in range(i - 1, -1, -1):
            perm[j], perm[i] = perm[i], perm[j]
        if check_permutation(perm):
            yield perm[:]

