import re

class TShirt:
    def __init__(self, size):
        self._size = size.upper()
        self._small_sizes = ['S', 'XXS', 'XS', 'SM']
        self._medium_size = 'M'
        self._large_sizes = [
            'L', '2XL', '3XL', '4XL', '5XL']
        self._bigger_sizes = self._large_sizes + ['INFINITY']

    def compare(self, other):
        if self._size < other._size:
            return -1
        elif self._size > other._size:
            return 1
        else:
            x_match = re.search(r'^.*?' + re.escape(other._size), self._size)
            if x_match:
                return len(re.findall('X|xx', self._size)) - len(re.findall('X|xx', other._size))
            elif re.search(r'^.*?' + re.escape(self._size), other._size): # check if self size is prefix of other size
                return -1
            else:
                # compare large sizes more robustly
                index = self._bigger_sizes.index(self._size)
                larger_other = self._bigger_sizes[index + 1] if index < len(self._bigger_sizes) - 1 else 'INFINITY'
                result = self._compare(other, larger_other)
                return result if result is not None else 0

    def _compare(self, other, larger_size):
        index_self = self._bigger_sizes.index(self._size) or len(self._bigger_sizes) - 1
        index_other = self._bigger_sizes.index(other._size) or len(self._bigger_sizes) - 1
        if index_self < index_other:
            return 1
        elif index_self > index_other:
            return -1
        else:
            # check against larger size specified in _compare method call arguments
            if self._size == larger_size:
                return 1    # current T-shirt is bigger than the other one
            elif other._size == larger_size:
                return -1   # the other T-shirt is bigger than the current one
            else:
                x_match = re.search(r'^.*?' + re.escape(larger_size), self._size)
                if not x_match and re.search(r'^.*?' + re.escape(larger_size), other._size):
                    return -1
                elif x_match and not re.search(r'^.*?' + re.escape(larger_size), other._size):
                    return 1
                else:
                    # compare X/xx-sized variants when neither is a larger size specified
                    size_matches = [re.findall('X|xx', x) for x in (self._size, other._size)]
                    num_x_matches_self, num_x_matches_other = map(len, size_matches)
                    if num_x_matches_self > num_x_matches_other:
                        return 1
                    elif num_x_matches_other > num_x_matches_self:
                        return -1
                    else:
                        # if both T-shirts have the same number of X and x characters,
                        # check if current one has it at a higher position in string
                        if re.search(r'^.*?' + re.escape(larger_size), self._size) is None:
                            return -1
                        else:
                            return 1
    def __str__(self):
        return self._size
def solve():
    t = int(input())
    for _ in range(t):
        a, b = input().split()
        t_shirt1 = TShirt(a)
        t_shirt2 = TShirt(b)
        print(t_shirt1.compare(t_shirt2))

from functype import total_ordering

@total_ordering
class ShirtSize:
    def __init__(self, size):
        self.size = size

    def __lt__(self, other):
        if 'S' in self.size and ('M' in other.size or 'XL' <= other.size <= 'XXXL'):
            return True
        elif 'L' in [s for s in other.size.split('X')] and (not 'X' in self.size or len(self.size.count('X')) < len(other.size.count('X'))):
            return True
        else:
            return False

    def __gt__(self, other):
        return other < self

    def __eq__(self, other):
        return self.size == other.size

def solve():
