from collections import defaultdict

def extend_and_calculate(n, heights, widths, gcd):
    if not heights or not len(heights) == n:
        return None

    extended_heights = [[None] * (gcd - h[0][0]) for h in heights]
    for idx, h in enumerate(heights):
        if h:
            for i in range(gcd - h[0][0]):
                if extended_heights[idx][i]:
                    return "Cannot arrange the given cheese slices."
                elif widths[idx][i] + 1 > gcd and not all(w >= 2 for w in heights[idx][i + 1:]):
                    extended_heights[idx][i] = [[0, 1]] * (gcd - h[0][0])

    perim = sum([extend_and_calculate(j, h[i], w, gcd) for i, j in enumerate(heights) if h[i]] + [sum([2 * w for w in wid]) + 4 for _, wid in zip(heights, widths) if not vid])
    return perim or None

def solve(*cheese_slides):
    if not cheese_slides:
        return ""

    gcd = min([x[0] for x in cheese_slides], default=1)
    for h, w in sorted(cheese_slides, reverse=True, key=(lambda x: x[0][0])):
        cheese_slides.extend([(h - i, w) for i in range(gcd - h[0]) if (h - i, w)] if h else [(h, w)])

    result = []
    for _ in range(len(cheese_slides)):
        perim = extend_and_calculate(1, (cheese_slides.pop(0),), ([c[i] for c in cheese_slides if i < len(c)],), gcd)
        if not perim:      break
        result.append(perim)

    return "\n".join((str(x) for x in result)) or ""

