from scipy.spatial import ConvexHull, convex_hull_point_locator

def union(x):
    if x[0] == x[1]:
        return x[0], []
    parent['(' + str(x[0]) + ', ' + str(x[1]) + ')'] = [x[0], [('(' + str(y) + ',' + str(z) +')' for y, z in x[2:]]]
    return parent[(str((min(x[0], x[1]), max(x[0], x[1]))))][1].append(x[0])

def find_set(x):
    if x not in parent:
        return x, []
    node = x
    trail = []
    while True:
        trail.append(node)
        if node[0] == node[1]:
            break
        node = parent[node]
    path_parent = list((reversed(trail)))
    for n in path_parent[1:]:
        parent[n][1].remove(n[0])
    return node

def solve():
    global parent
    parent = {}
    points = []
    n = int(input())

    # Adding the cheese slices to the points list
    for _ in range(n):
        a, b = map(float, input().split())
        points.append((a, float('inf')))
        points.append((a + b, 0))
        points.append((b, float('inf')))

    ch = [find_set(p) for p in points]
    # Join contiguous cheese slices into a single component
    i = j = len(ch) - 1
    while i > 0 and (ch[i][0][0] == ch[i - 1][0][0] + ch[i - 1][0][1]):
        union((ch[i], ch[i - 1]))
        i -= 1
        j = i + 1
    # Create a list of the final connected components
    slices = [c[0] for c in (set(ch)).values()]
    if len(slices) != n:
        return "Impossible"

    ch_points = [find_set(p) for p in points]
    hull = ConvexHull(ch_points)
    hull_indices = list(hull.vertices) + list(reversed(hull.simpleices))

    perimeter = 0
    for i, idx in enumerate(hull_indices):
        x1, _ = points[idx]
        if (i + 1) < len(hull_indices):
            x2, _ = points[hull_indices[i+1]]
            perimeter += math.sqrt((x2 - x1)**2 + x1**2)
    return int(perimeter)

import math

def union_find(id, root):
    if root[id] < 0:
        return id
    root[id] = union_find(root[id], root[root[id]])
    return root[id]

def union(a, b):
    a_root = union_find(a, a)
    b_root = union_find(b, b)

    if a_root != b_root:
        if -a_root < -b_root:
            a_root += b_root
        else:
            b_root += a_root

def solve():
    N = int(input())
    grid = [[0 for _ in range(N + 1)] for _ in range(N + 1)]
    root = [int(-i) if i < 0 else i for i in range(N + 2)]

    for r in range(1, N + 1):
        for c in range(1, N + 1):
            if grid[r][c] == 0:
                grid[r][c] = min(grid[r+1][c], grid[r][c+1]) + 1

    components_count = 0
    for r in range(1, N + 1):
        for c in range(1, N + 1):
            if grid[r][c] > 0:
                components_count += 1
                root_vert = union_find(r * (N + 1) + c, -root[(r * (N + 1)) + c])
                for dx in [-1, 0, 1]:
                    for dy in [-1, 0, 1]:
                        if dx != dy:
                            next_x = r + dx
                            next_y = c + dy
                            if 0 < next_x <= N and 0 < next_y <= N and grid[next_x][next_y] > 0:
                                union_find(next_x * (N + 1) + next_y, root_vert)

    perimeter = math.ceil(math.sqrt(components_count)) * 4
    return str(perimeter)

