from math import sqrt

def is_prime(n):
    if n <= 1:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0:
        return False
    root = int(sqrt(n)) + 1
    for i in range(3, root, 2):
        if n % i == 0:
            return False
    return True

def next_prime(n):
    n += 2
    while True:
        if is_prime(n):
            break
        n += 2
    return n

