import math
def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def find_non_prime_summand(n):
    candidates = list(range(3, min(n * 2, 10**5) + 1))
    for candidate in candidates:
        if not is_prime(candidate):
            continue
        summand = n + candidate
        if not is_prime(summand):
            return candidate
    raise ValueError("This should never be executed.")

