import collections
from itertools import product

def is_isolated(x, y):
    visited = set()
    visited.add((x, y))
    moves = [(x + d1, y + d2) for d1, d2 in itertools.product([-1, 0, 1], repeat=2) if (0 <= x + d1 <= y and 0 <= y + d2 < len(visited))]
    for row, col in moves:
        if (row, col) in visited:
            break
        if check_neighbour((x + d1, y + d2)):
            return False
    return True

def check_neighbour(location):
    global board
    if location in board:
        return True
    return False

def bfs(start_row, start_col):
    queue = collections.deque()
    start = (start_row, start_col)
    queue.append(start)
    visited = set((start_row, start_col))
    next_steps = [(start_row + dr, start_col + dc) for dr, dc in itertools.product([-1, 0, 1], repeat=2)]

    while queue:
        node = queue.popleft()
        if is_isolated(*node):
            yield node
        for dr, dc in next_steps:
            next_cell = (node[0] + dr, node[1] + dc)

            if next_cell not in visited and check_neighbour(next_cell):
                queue.append(next_cell)
                visited.add(next_cell)

def solve(n, m):
    board = [[False] * m for _ in range(n)]
    solution = []

    # populate the board with 'True' for isolated cells found by bfs
    for row, col in bfs(0, 0):
        if 0 <= row < n and 0 <= col < m:
            board[row][col] = True

    result = []
    for i, row in enumerate(board):
        for j, cell in enumerate(row):
            if cell:
                result.append((i+1,j+1))
    return result

import functools

# This code generates Python 3 code as per the user's instruction

def solve(grid_size):
    # Initialize the grid and track isolated cells
    grid = [['.' for _ in range(grid_size)] for __ in range(grid_size)]
    isolated_cells = set()

    # Fill out the grid with knight moves (using recursive function)
    def knight_moves(row, column):
        for r, c in ((-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)):
            if 0 <= row + r < grid_size and 0 <= column + c < grid_size:
                grid[row+r][column+c] = '#'
                # Check for isolation (skip already-marked cells)
                if not grid[row+r][column+c] in isolated_cells:
                    knight_moves(row + r, column + c)
                    isolated_cells.add(grid[row+r][column+c])

    # Handle the corners (if present, to cover grid sizes 3 and larger)
    if grid_size >= 3:
        knight_moves(0, 0)
        knight_moves(grid_size-1, 0)
        knight_moves(0, grid_size-1)
        knight_moves(grid_size-1, grid_size-1)
    else:
        # Use a simple for loop to fill out grid for corner cases (e.g., 2x2 grid)
        for row in range(grid_size):
            for column in range(grid_size):
                grid[row][column] = '#'
                knight_moves(row, column)

    # If isolated cells exist (i.e., more than one cell), pick the first found
    if len(isolated_cells) > 1:
        coord = next((c for c in isolated_cells if '.' == c[0][0]))
        return coord

    # If no isolated cells exist, pick a random cell from the grid
    else:
        row, column = sorted(random.choice(grid))[::-1]
        return (row, column)

from collections import deque

def solve(n, m):
    g = [[0] * m for _ in range(n)]
    g[0][0] = 1

    v = set()
    q = deque()
    q.append((0, 0))
    v.add((0, 0))

    moves = [(-2, -1), (-2, 1), (2, 0), (0, 2), (0, -2)]

    while q:
        x, y = q.popleft()
        for dx, dy in moves:
            nx, ny = x + dx * 2, y + dy
            if (nx < len(g) and ny >= 0 and nx < len(g[0]) and ny < len(g)):
                if g[nx][ny] == 0:
                    g[nx][ny] = g[x][y] + 1
                    q.append((nx, ny))
                    v.add((nx, ny))

    for i in range(len(g)):
        for j in range(len(g[0])):
            if len(g[i][j]) == 1:
                return i, j
    # Return an arbitrary cell when there is no isolated cell found.
    return sorted(range(n)), sorted(range(m))[0]

