import math
from itertools import combinations

def solve(n):
    if n < 3:
        raise ValueError("The input day number should be greater than or equal to 3.")

    days_off = []
    working_days = list(range(1, n))
    days_off.append(working_days[0])   # First day is a working day since it has no preceding day
    days_off.append(n)                # Last day is a day off, as stated in the problem description

    for group in combinations(working_days, 3):
        diff_sum = sum([abs((days_off[i] - days_off[i+1]) - (days_off[i+2] - days_off[i+1])) for i in range(len(group)-1)])
        if diff_sum <= 0:
            continue

        segment_lens = [(days_off[i+1] - days_off[i]) - (days_off[i+2] - days_off[i+1]) for i in range(len(group)-1)]
        if len({segment_lens}) == 1:
            continue

        min_diff = math.ceil(diff_sum / 3)
        if max(segment_lens) - min(segment_lens) <= min_diff:
            continue

        return min_diff
    else:
        return None  # Return None if no valid day off combinations are found

