    dp = [0] * (64 - N)

    for i in range(len(dp)):
        dp[i] = 1
        if i + 2 <= len(dp):
            diff = max(diff, dp[i] - dp[i+2])

    for i in reversed(range(len(dp) // 2, -1, -1)):
        dp[i] += dp[i+1] << 1
        if i + 3 <= len(dp):
            diff = max(diff, dp[i] - dp[i+3])

