def solve(n: int):
    if n <= 0:
        print("Invalid input. Please enter a positive integer for N.")
        sys.exit(1)

    torch_position = [["."] * (2 * n - 1) for _ in range(n)]
    torch_position[0] = ["#"*(i+1) for i in range(2*n-1)]

    def get_neighbors(x: int, y: int) -> List['int']:
        neighbors = []
        if 0 < x < len(torch_position) - 1 and 0 < y < len(torch_position[0]) - 1:
            for dx, dy in ((-1, 0), (0, -1), (0, 1), (1, 0)):
                neighbors.append((x + dx, y + dy))
        return neighbors

    def bfs(start_x: int, start_y: int):
        visited = {(start_x, start_y)}
        frontier = bh.PriorityQueue()
        frontier.push((0, (start_x, start_y)))

        while not frontier.empty():
            _, current = frontier.pop()
            torch_position[current[0]][current[1]] = "#"
            visited.add(current)

            for neighbor in get_neighbors(*current):
                if neighbor not in visited:
                    frontier.push((1, neighbor))

        return visited

    try:
        solution = bfs(0, (2*n-1) // 2)
        for row in torch_position:
            print(" ".join(row))
    except Exception as e:
        print("An error occurred during solving the problem.")
        print("Please verify the input or consult the user guide.")
        return

import math

def solve(n, a):
    max_len = max(a)
    if max_len <= 2 or n <= 3:
        return 0

    # Sort the lengths of the sticks in non-increasing order
    a.sort(reverse=True)

    # Calculate the difference between the maximum and the minimum length
    diff = math.floor((max_len - 1)**2 / 4.0)

    # Check if it's possible to make a stick equal to max_len-2 with operations
    for i in range(n):
        if abs(a[i] - (max_len - diff)) <= 1:
            break

    # Decrease the maximum length by the difference and perform operations to make the minimum length equal to 1
    for i in range(n-1, -1, -1):
        if a[i] > 1:
            if a[i] > max_len - diff:
                a[i] -= diff
            else:
                a[i] = max_len - a[i]

    # Return the minimum number of operations required to form an equilateral triangle, or -1 if it's impossible
    return len(a) == 3 and all(map(lambda x: abs(x - 1) <= 0.001, a)) and diff >= 0 else -1

