        return float('inf')
    smallest = min(sticks)
    difference = int((math.sqrt(8 * smallest**3 + 54 * smallest**2 - 144 * smallest + 84) + math.sqrt((8 * smallest**3 + 54 * smallest**2 - 144 * smallest + 84)**2 - 486 * smallest**2)) / 6)
    operation_count = difference + (smallest - sticks[0]) // 2
    overlapping_sticks = [sticks[i] for i, stick in enumerate(sticks) if stick != smallest and 0 < sticks[i] <= smallest + difference * 3]
    if len(overlapping_sticks) > 1: # check for multiple overlapped sticks
        return float('inf')
    elif operation_count >= len(overlapping_sticks):
        operation_count = min(len(overlapping_sticks), operation_count) # ensure each overlapping stick requires at most one op operation
    else:
       overlapping_sticks = [None] * len(sticks)

    for i, stick in enumerate(sticks[:-1] if overlapping_sticks else sticks):
        possible_change = difference - (stick - smallest) // 2
        if possible_change > 0:
            for j in range(i + 1, len(overlapping_sticks)):
                if abs(possible_change) == abs(overlapping_sticks[j] - stick):
                    overlapping_sticks[j] = 'changed' # mark the stick that requires alteration
            operation_count += possible_change

    if operation_count > len([True for s in overlapping_sticks if s == 'changed']):
        return float('inf') # ensure total operations count matches the actual number of altered sticks

    return operation_count

from collections import defaultdict

class Node:
    def __init__(self, key):
        self.key = key
        self.index = None
        self.indices = []

def make adjacencyList(n, k, arr):
    nodes = defaultdict(Node)
    offset = arr[0] % k
    for i in range(len(arr)):
        element = (arr[i] - offset) // k
        if element not in nodes:
            nodes[element] = Node(element)
        if nodes[element].index is None:
            nodes[element].index = i
        nodes[element].indices.append(i)
    return nodes

def getMaxScore(nodes, k):
    max_score = 0
    visited = set()

    def dfs(node, index):
        if node.key not in visited:
            score = len(node.indices) * k
            for i in range(index + 1, len(node.indices)):
                score += abs(node.indices[i] - node.indices[(index - 1) % len(node.indices)])
            max_score = max(max_score, score)
            visited.add(node.key)
            for neighbour in nodes[node.key].indices:
                dfs(nodes[neighbour], node.indices[(index + 1) % len(node.indices)])

    for node in nodes.values():
        if node.index is not None and node.key not in visited:
            dfs(node, node.index)

    return max_score

