from math import inf
import sys

def solve(orbits, cost):
    n = len(orbits)
    min_cost = inf

    # Memoized table to store the minimum cost for each sub problem.
    memo = [0] * (n+1)

    if n == 0:
        return 0
    elif n == 1:
        return orbits[0] * cost

    for i in range(n):
        if orbits[i] > 1:
            destroy_orbit = (orbits[i] - 1) * cost
            memo[orbits[i]] = min(memo[orbits[i]], destroy_orbit)
    for i in range(n):
        if orbits[i] > 1:
            memo[1] += min(memo[orbits[i]], (orbits[i] - 1) * cost)
    for i in range(1, n+1):
        min_cost = min(min_cost, memo[i])
    return min_cost + orbits[0]

