import collections
def solve(t):
    if len(t) == 0: # handle empty string case as an edge case
        return ''

    alphabet = list('abcdefghijklmnopqrstuvwxyz')
    digits_count = collections.Counter(map(int, t))

    decoded_string = []

    for digit in reversed(sorted(digits_count)):
        count = digits_count[digit]
        while count > 0:
            if len(decoded_string) == 0 or int(''.join(reversed(decoded_string[-1])) + str(digit)) < alphabet.index(decoded_string[-1][-1]):
                decoded_string.append(str(alphabet[alphabet.index(t[-count]) % len(alphabet)]))
            count -= 1
    return ''.join(reversed(decoded_string))

