import sys

def next_permutation(perm):
    n = len(perm)
    i = n-1
    while i > 0 and perm[i-1] >= perm[i]:
        i -= 1
    if i <= 0:
        return False
    j = n
    while perm[j-1] <= perm[i-1]:
        j -= 1
    perm[i-1], perm[j-1] = perm[j-1], perm[i-1]
    start = i
    end = n-1
    while start < end:
        perm[start], perm[end] = perm[end], perm[start]
        start += 1
        end -= 1
    return True

def generate_perm_and_values(perm):
    value = 0
    permutations = set([tuple(perm)] + list(map(tuple, itertools.permutations(perm))))
    for p in permutations:
        if sum(p[i] if p[i] > value else 0 for i, p_i in enumerate(p)) > value:
            break
        yield (list(p), value)
        value += p[i] - (value if p[i] > value else 0)

