import itertools, operator

def is_valid(n):
    return 4 <= n <= 100

def solve(n):
    max_value = float('-inf')  # Initialize minimum possible value as negative infinity
    perm_with_max_value = []   # Initialize permutation with maximum value as empty list

    if not is_valid(n):
        raise ValueError("Invalid input: n should be between 4 and 100.")

    # Generate all possible permutations
    perms = itertools.product(range(n), repeat=n)
    for perm in perms:
        value = sum([perm[i] + i - len(perm) + 1 for i in range(len(perm))])
        if value > max_value:
            max_value = value
            perm_with_max_value = [perm[:]]
        elif value == max_value and perm != perm_with_max_value[0]:
            perm_with_max_value.append([perm[:]])

    return perm_with_max_value

import heapq

def solve(n):
    # edge case: if n is smaller than 4, the solution is the identity permutation
    if n < 4:
        return list(range(1, n+1))

    # create a priority queue with the first element being (permutation score, current permutation)
    heap = [(0, tuple(range(1, n+1)))];

    while heap:
        # get the top permutation from the priority queue and remove it
        (score, cur_perm) = heapq.heappop(heap)

        # check if this is the solution
        if len(cur_perm) == n:
            return cur_perm

        # add the new permutation with its score to the priority queue if it hasn't been visited
        for i in range(n):
            if i+1 < len(cur_perm):
                next_score = score + (cur_perm[i] if cur_perm[i] < cur_perm[i+1] else 0)
                heapq.heappush(heap, (next_score, list(cur_perm)))

