from collections import Counter
import itertools

def solve(n: int, cnt: list) -> int:
    differ_pairs = [abs(c1 - c2) for (c1, c2) in itertools.combinations(cnt, 2)]
    odd_diff = [d for d in differ_pairs if d % 2 == 1]

    if not odd_diff:
        return sorted(cnt.keys())[0]

    for c1, c2 in itertools.combinations(cnt.keys(), 2):
        if cnt[c1] - cnt[c2] in odd_diff:
            return solve(n, Counter({k: v for k, v in cnt.items() if k != c1 and k != c2}) - {c1, c2} + Counter({c1: cnt[c1]-2, c2: cnt[c2] - 2}))
    raise ValueError("Input is invalid or no valid moves are found.")

