class DisjointSet:
    def __init__(self, n):
        self.parent = [i for i in range(n)]
        self.rank = [0]*n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    # Using the "union by rank" optimization
    def union(self, x, y):
        rx = self.find(x)
        ry = self.find(y)

        if rx == ry:  # Short-circuit; sets already merged
            return

        if self.rank[rx] > self.rank[ry]:
            self.parent[ry] = rx  # Path Compression
        else:
            self.parent[rx] = ry   # Path Compression

        self.rank[ry] += 1  # Improve path from y to r1 (root of y)

def solve():
    dset = DisjointSet(total_cnt)

    n, total_cnt = map(int, input().split())
    cnt = list(map(int, input().split()))

    # Merge connected components as our equivalent operation for taking two balls of different colors
    for i in range(len(cnt)):
        for j in range(i+1, len(cnt)):
            dset.union(i*total_cnt + cnt[i], j*total_cnt + cnt[j])

    grouped = set()
    for i in range(len(cnt)):
        root = dset.find(i*total_cnt + cnt[i])
        if root not in grouped:
            grouped.add(root)

    assert len(grouped) == 1, "All the remaining balls must have the same color"
    return list(grouped)[0]

import math

def solve(N, M):
    max_sum = (N * M) // 2 + (N - 1) * M

    tiles = [[False] * (2 * M) for _ in range(N)]
    count = 0

    for i in range(1, max_sum + 1):
        row = i // M
        tile = i % M
        if not tiles[row][tile]:
            tiles[row][tile] = True
            if tile > 0:
                left_tile = (tile - 1) % M
                if row + 1 <= N and not tiles[row+1][left_tile]:
                    tiles[row+1][left_tile] = True
                    count += 1

            if tile < M:
                right_tile = (tile + 1) % M
                if row + 1 <= N and not tiles[row+1][right_tile]:
                    tiles[row+1][right_tile] = True
                    count += 1
    return count

