# Function docstring describing what solve() does
def solve(N: int, M: int) -> int:
    # Initialize a 2D list to store numbers in the grid
    grid = [[0] * (2 * M) for _ in range(N)]

    # Fill the grid with numbers as described in the problem
    for i, m in enumerate([x for x in range(1, M + 1)]):
        grid[0][m - 1] = m
    for r in range(1, N):
        for col in range(r * M, (r + 1) * M):
            grid[r][col] = col - (r - 1) * M

    # Count and return the number of distinct tight dominoes
    count, nums = 0, set()
    for i, row in enumerate(grid):
        for j, num in enumerate(row):
            if num != 0:
                if num + 1 in grid[i] or (j + 1 < len(grid[i]) and grid[i][j+1] != 0 and grid[i][j+1] == num+1):
                    count += 1
                    nums.add(num)

    return count

