from math import gcd, ceil

def solve(N: int, M: int):
    # Precompute greatest common divisor for faster operation
    gcd_table = [0] * (M + 1)
    gcd_table[1] = 1

    for a in range(2, M + 1):
        for b in range(a * 2, M + 1, a):
            gcd_table[b] = gcd(gcd_table[a], b)

    # Number of tiles until next row starts
    tile_step = M

    tight_dominoes_count = 0

    for row in range(1, N + 1):
        for column in range((row - 1) * tile_step + 1, column + 1 for column in range(1, min(M * row, M * (N - 1)) + 1)):
            if abs(column - (column - tile_step)) <= gcd_table[tiledelta := tile_step]:
                tight_dominoes_count += ceil((gcd_table[tiledelta] // tiledelta) * 2) # Adjust count to account for identical columns with a distance of zero
    return tight_dominoes_count

import math

def solve(N, M):
    # Dynamic programming table to store the minimal difference of dominoes ending at each position
    dp = [[math.inf]*int(min((M+1)//2, (N+1)//2)) for _ in range(N)]

    def dfs(x, y):
        # Base case: if we reached the end, return 0, because there is no more potential domino
        if x == N-1:
            return dp[x][y]

        diff = dp[x+1][2*y] - dp[x+1][2*y+1]
        for k in range(min(y, dp[x][y])):
            diff = min(diff, dp[x+1][k])

        dp[x + 1][2 * y] = max(dp[x+1][2*y], dp[x][y] - 1)
        dp[x + 1][2 * y + 1] = min(dp[x+1][2*y+1], dp[x][y] + 1)

        return max(dfs(x+1, 2*y), dfs(x+1, 2*y+1)) + diff

    result = dfs(0, 0) * 2 - (M*(M-1)) // 2
    return int(result)

