import sys

def solve(test_cases):
    invalid_input = False

    for case in test_cases:
        if not isinstance(int(case[0]), int) or (not 1 <= int(case[0]) <= 1000):
            invalid_input = True
            break

        if not re.match(r'^[a-z]{2,8}$', '\n'.join(case)):
            invalid_input = True
            break

    if invalid_input:
        print("Invalid Input:", file=sys.stderr)
        return

    for case in test_cases:
        # make input 2D and add each row to the img list
        img = [list(a) for a in zip(*[iter(row)]*2) for row in case[1:]]

        freq = Counter(img)          # count frequency of each color

        # If all images have same color, return 0
        if len(freq) == 1:
            print(0)
            continue

        # Define pairs of pixels with the same color
        pairs = dict()
        for idx, row in enumerate(img):
            for i, col in enumerate(row):
                key = (idx,i) if len(img) > 1 else ('', '')  # update key for 2D or 1D input
                if col in pairs:
                    pairs[key].append((idx, i))      # add the coordinates to the existing pair
                else:
                    pairs[key] = [(idx, i)]          # create a new pair with single coordinate

        moves_needed = 0
        for pair in pairs.values():
            if len(pair) > 1:      # calculate moves needed for each pair of pixels
                moves_needed += 1

        print(moves_needed)    # output the calculated number of moves

