def i_mod_n(a, n):
    """A helper function that finds (a % n) using Euclid's Algorithm"""
    gcd = __gcd(a, n)
    return a if gcd != n else (a - n) % n

def solve(n, k):
    """Checks if there is a split into pairs that satisfy conditions"""
    if not all([len(pair) == 2 for pair in zip(n, i_mod_n(k, n))]):
        return 'NO'

    # Check validity of the pair with respect to positions and k value
    pair = zip(n,i_mod_n(k,n))
    valid_pair = any([sum(x) == k for x in pair])

    if valid_pair:
        return 'YES' + '\n' + '\n'.join(' '.join(map(str, pair)) for pair in zip(n,i_mod_n(k,n)))
    else:
        return "YES"  # The pairs are valid, but no such set of pairs adds up to k

