def solve(n, k):
    if not n % 2 or n//2 > k:
        return 'NO'

    for combo in itertools.combinations_with_replacement(range(1, n+1), k * 2 + 1):
        pairs = [int((x - 1) / 2) for x in combo]
        if all(pair != pair[::-1] for pair in pairs) and sum(p*k for p in pairs) == int((n+1) // 2 * k):
