def split_even(n, k=0):
    if n % 2 != 0:
        return False
    first = 2 if k == 0 else max((j + k) // 4 for j in range(1, n // 2))
    second = n - first if k == 0 else (n - first) if first % k == 0 and first * k % 4 == 0 else None
    return True if second else False

