def isvalid(x, y, board):
    return (board[y] % 2 != (x % 2)) and (0 <= x < len(board) and 0 <= y < len(board[0]))

def can_win(board):
    def backtrack(x, y, player):
        if not isvalid(x, y, board):
            return False
        elif (x == len(board) - 1 and y == len(board[0]) - 1) or len([b for b,c in product(board, repeat=2) if c == (not player and isvalid(b[0], b[1], board)) or (player and backtrack(b[0], b[1], not player))]) <= 1:
            return player
        else:
            for b in product(range(len(board)), range(len(board[0]))):
                if backtrack(b[0], b[1], not player):
                    return True
            return False
    return backtrack(0, 0, 0) != 0

