from functools import lru_cache

def can_move(x: int, y: int) -> bool:
    return (x or not (y % 2)) or (y or not (x % 2))

@lru_cache((type(None), type(None)), maxsize=16)
def solve(n, m):
    if n == 0 or m == 0:
        return "Burenka"

    for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
        n_new, m_new = n + dx, m + dy
        if can_move(n_new, m_new):
            if solve(n_new, m_new) != "Burenka":
                return "Tonya"
    return "Burenka"

