from collections import deque

def solve(n, m):
    queue = deque([(0, 0)])
    visited = set((0, 0))
    moves = {(-1, 1), (1, 1)} if n % 2 == 1 else {(-1, 1), (-1, -1), (1, 1), (1, -1)}

    while queue:
        x, y = queue.popleft()

        if (x, y) == (n - 1, m - 1):
            return "Tonya"

        for dx, dy in moves:
            nx, ny = x + dx * 2, y + dy * 2

            # If the chip is in a yellow cell (not red), check all possible moves and find one valid move if exists
            if (nx >= 0 , nx < n, ny >= 0, ny < m) and ((nx, ny) not in visited):
                queue.append((nx, ny))
                visited.add((nx, ny))

    return "Burenka"

