import collections

def bfs(grid, src, dest):
    queue = collections.deque([(src, 1)])
    visited = set()

    while queue:
        node, cost = queue.popleft()
        if node == dest:
            return cost
        elif node not in visited:
            visited.add(node)
            for neighbor in [(node[0] + 1, node[1]), (node[0], node[1] + 1), (node[0] - 1, node[1]), (node[0], node[1] - 1)]:
                if 0 <= neighbor[0] < len(grid) and 0 <= neighbor[1] < len(grid[0]) and (neighbor not in visited or grid[neighbor][0] == 0):
                    queue.append((neighbor, cost + 1))
    return -1  # returns error if no path found

