        src_cost = bfs(grid, (src % rows, src // cols), (dest % rows, dest // cols))

        energy = 2 * src_cost - grid[(src // cols)][(src % cols)] if grid[(src // cols)][(src % cols)] !=0 else 0
        print("The minimum energy required is:", energy)

