from itertools import chain, count, permutations

def solve(s):
    max_digit = 9
    missing = set([i for i in range(10)])
    numbers = set()
    for digit in range(max_digit, -1, -1):
        if digit <= s:
            for perm in permutations(range(1, max_digit + 1)):
                num = sum(perm) + (len(perm) * digit)
                if num == s and len(set(perm)) == len(perm):
                    numbers.add(num)
                    missing.update(perm)
    remaining_digits = list(missing - set([s % 10]))
    res = sorted(list(reversed(remaining_digits)))
    digits: list[int] = []
    for _ in res:
        if len(digits) >= _:
            break
        digits.append(_)
    answer = sum([digit * len(digits) + remainder for digit, remainder in enumerate(digits)])
    print(answer)

