    digit_sum = sum(digits) * int(s / n)

    # For smaller sum of digits, the number must be less than 9 repeated n times
    if digit_sum < s:
        return str(9 * n - (n-1))

    used_digits = set()
    for c in combinations(list(sorted(digits)), n):
        candidates = list(filter(lambda x: sum(x) == s - digit_sum, permutations(c)))
        if candidates:
            return str(*sorted(candidates[0]))

    raise Exception("Test case failed.")

