def find_min_varied_num(n):
    seen = set()

    def _find(n, cur=0):
        if n == 0:
            return ['0']

        for digit in range(1, 10):
            d = str(digit)
            if d not in seen:
                seen.add(d)
                remaining = _find(n - digit, cur + digit)
                if remaining:
                    return [str(digit)] + remaining
        return []

    return min((''.join(nums), int(''.join(sorted(nums))) for nums in (_find(n) for _ in range(10))))[0]

