from collections import deque

def solve(n: int, a: list):
    q = deque()
    seen = set()

    # Add each number to the queue and the seen set
    for num in a:
        q.append(num)
        seen.add(num)

    # Keep removing elements from the queue and the beginning of the sequence until all remaining numbers are unique
    while len(q) > len(seen):
        smallest = q.popleft()
        del seen[smallest]
        if smallest - 1 in seen:
            q.appendleft(smallest - 1)
    return n - len(seen)

