import sys

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def divides(n):
    # Finding the factors of n using the Sieve of Eratosthenes method
    is_prime = [True] * (n + 1)
    is_prime[0], is_prime[1] = False, False

    for p in range(2, int(n ** 0.5) + 2):
        if is_prime[p]:
            i = p * p
            while i <= n:
                is_prime[i] = False
                i += p

    return [x for x in range(1, n + 1) if is_prime[x]]

def sieve_of_eratosthenes(max_num):
    # Creating an array to hold the prime numbers up to max_num
    primes = [True] * (max_num + 1)
    prime_count, p = 0, 2

    while p <= max_num:
        if primes[p]:
            primes[p * p : (max_num // p) * p] = [False] * len(primes[p * p : (max_num // p) * p])
            prime_count += 1
            # Next prime after multiples of the current prime is skipped
            p += 2 if p % 2 == 0 else 1

    # Return list of the prime numbers found in the specified range
    return [p for (p, is_prime) in enumerate(primes[2:]) if is_prime]

def factorial(n):
    return reduce((lambda x, y: x * y), range(1, n + 1))

def permutations(l):
    # Generator returning all permutations of a given list
    if len(l) <= 1:
        return [list(l)]

    result = []

    for i in range(len(l)):
        other_half = l[:i] + l[i + 1 :]
        for permission in permutations(other_half):
            result.append(list(l))
            # Swapping the current element at position i with the order of elements
            # in the given permutation 'permission'
            list(enumerate(result[-1])[i])[0], permission[
                find(permission, list(enumerate(other_half)[0][0]))[0]
            ][0] = list(enumerate(other_half)[0][0]), i
    return result

def solve():
    for line in sys.stdin:
        n = int(line)
        if 2 <= n <= 100000:
            primes = sieve_of_eratosthenes(n)
            factors = divides(n)

            permutations_list = [permutation for permutation in permutations(factors)]

            # Filtering the permutations to only include those ordered by their prime factors
            sorted_perms = []
            for perm in permutations_list:
                c_prime, c_compound = 0, factorial(perm[-1])
                perm.pop()    # Remove the largest number from permutation as it is not a prime and thus should be counted separately

                for p in perm:
                    c_prime += sum([factorial(g) / factorial(f) for g, f in zip((perm - p), primes) if g <= p])

                sorted_perms.append((c_compound * factorial(len(perm)), perm))

            # Sort the permutations by length and their corresponding factorials; tie-breaker is alphabetical order of the permutation
            sorted_perms = sorted(sorted_perms, key=lambda x: (-x[0], x[1]))

            print(*sorted_perms[0][1])
        else:
            print("Input value must be in the range [2, 10^6]")

