def calculate_weight(perm):
    return sum(1 for i, x in enumerate(perm) if i + 1 == x)

def generate_permutations(n):
    return list(combinations(range(1, n + 1), n))

def find_minimal_permutation(n):
    perms = [list(p) for p in generate_permutations(n)]
    weights = [calculate_weight(perm) for perm in perms]
    min_idx = min(range(len(weights)), key=lambda i: weights[i])
    return perms[min_idx]

