from pyomo.env import *

def solve():
    model = AbstractModel()
    model.n = OptVar(within=NonNegativeIntegers)
    model.x = Var(range(1, model.n + 1), domain=NonNegativeIntegers)

    def objective_rule(model):
        return sum(model.x)

    model.Obj = Objective(rule=objective_rule, sense=minimize)

    def divisibility_rule(model, i):
        if i!=1:
            return (sum(model.x[(i-1)]*j for j in range(i)) - (model.n/i)*model.x[i]) > 0
        else:
            return True

    model.Div = ConstraintList([divisibility_rule(model, i) for i in range(1, model.n)])

    def average_rule(model):
        return sum(model.x)/model.n - model.x[(model.n-1)] + 0.5

    model.Avg = Constraint(rule=average_rule)

    solver = SolverFactory('glpk')
    results = solver.solve(model)

    if not results[SolverStatus].success:
        print("No solution found.")
        return

    perm = [0] * model.n
    for i in range(1, model.n + 1):
        perm[i - 1] = int(model.x[i])

    print(' '.join(str(perm[i]) for i in range(model.n)))

