import math

def solve(x, a, b, c):
    keys = set([x] + list(chain.from_iterable(combinations((a, b, c), r=2)) if a != b != c else [x]))
    total_doors = {1, 2, 3}

    # count doors already opened or key is present
    opening_doors = 0
    for key in keys:
        if sum(map(lambda door : (key == door) or (key-door)//gcd(key, door), total_doors)) > 1:
            opening_doors += 1

    # check if all doors can be opened with the remaining doors
    remaining_doors = total_doors - keys

    required_keys = sum(remaining_doors - set([x]) // len(remaining_doors) + 1)
    if keys - set([x]) >= total_doors - set([x]) and required_keys <= opening_doors:
        return "YES"
    else:
        return "NO"

