    max_val = 10**6
    a = list(map(int, input().split()))
    if len(a) != n or any(x < 1 for x in a):
        return "Invalid input"
    if n == 0:
        return "YES"

    graph = [[] for _ in range(n)]
    visited = [False] * n

    for i, num in enumerate(a):
        for j in range(i+1, n):
            if abs(num - a[j]) <= max_val:
                graph[i].append(j)
                graph[j].append(i)

    def dfs(node, visited):
        if visited[node]:
            return False

        visited[node] = True

        if all(visited[child] for child in graph[node]):
            return True

        for child in graph[node]:
            res = dfs(child, visited)
            if res:
                return True

        visited[node] = False
        return False

    if dfs(0, [False]*n):
        return "YES"

    return "NO"

def initialize_s(n, m):
    s = [0]* (2*m)
    return s

def union_find(parent, rank, n, m, seq, x, y):
    root_x = find(parent, x)
    root_y = find(parent, y)

    if root_x != root_y:
        if rank[root_x] < rank[root_y]:
            parent[root_x] = root_y
            rank[root_y] += rank[root_x]
        else:
            parent[root_y] = root_x
            rank[root_x] += rank[root_y]

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def solve(n, m, seq):
    s = initialize_s(n, m)
    parent = [i for i in range(2*m)]
    rank = [1]* (2*m)

    # Apply operations on the string `s`
    for i in range(n-1, -1, -1):
        merged_component = find(parent, seq[i])
        s[merged_component] = 'A'
    merged_component = find(parent, s[-m])

    # Set first character as 'B' and process remaining characters as above
    s[0] = 'B'
    for i in range(1, len(s)):
        if find(parent, s[i-1]) != find(parent, s[i]):
            merged_component = find(parent, s[i])
            parent[merged_component - m] = merged_component
            s[i] = 'A'
    result = ""
    for i in range(len(s)-m, len(s)):
        result += s[i]

    if len(result) < m:
        missing_char = "B" if "B" not in result else "A"
        while len(result) < m:
            merged_component = find(parent, result[-1])
            parent[merged_component - m] = merged_component + 1
            result.append(missing_char)
    return "".join(result)

