def solve(n, s):
    # initialize dictionary to count balloons per problem
    counts = {ch: 0 for ch in set(s)}

    # initialize dictionary mapping maximum index of each problem
    max_indices = {}

    # iterate through the problems
    for i, ch in enumerate(s):
        # if problem is seen for the first time
        if not ch in max_indices:
            # set current index as its max index
            max_indices[ch] = i

        # increment balloon count for the current problem by 1
        counts[ch] += 1

    # calculate the cumulative total of balloons received
    result = sum(counts.values())

    # add additional balloons for initial solvers
    for ch in max_indices:
        result += max_indices[ch]

    return result

