from sys import stdin, stdout

def solve(s, dp={"": 0}):
    if len(s) in dp:
        return dp[len(s)]

    for i in range(1, min(4, len(s)) + 1):
        substr = s[:i]
        if substr not in dp or dp[substr] > len(s) - i:
            dp[substr] = len(s) - i
        ans = 1 + solve(s[i:])
        if ans < dp[len(s)]:
            dp[len(s)] = ans
    return dp[len(s)]

