import itertools
from functools import reduce

def gcd(a, b):
    return a if b == 0 else gcd(b, a % b)

def extended_ Euclidean_algorithm(a, b):
    if b == 0:
        x = 1
        y = 0
        d = a
    else:
        x, y = extended_Euclidean_algorithm(b, a % b)
        d = b

    if a < 0:
        x *= -1

    return x, y, d

def solve(n):
    max_cost = 0
    max_permutation = []

    # Iterate through all possible combinations of (d,perm)
    for d in range(1, n // 2 + 1):
        if gcd(max_cost, n) == 1:
            for perm in itertools.permutations(range(1, n)):
                cost = reduce((lambda a, b: a * d + b), perm, 0)
                if max_cost < cost:
                    max_cost = cost
                    max_permutation = list(perm)

    return max_cost, max_permutation

from itertools import combinations_with_replacement, permutations, count
import collections
from functools import lru_cache

@lru_cache(maxsize=None)
def solve(n):
    if n <= 1:
        return 1, [f"{i}" for i in range(1, n+1)]

    max_cost = -1
    max_perm = None
    max_d = None

    for d in count(1):
        perm_costs = {cost: [] for cost in range(d * (n-1) + 1)} # Cache permutation costs based on given conditions
        for perm in permutations(range(1, n+1)):
            cst = sum([abs(perm[i] - perm[i+1]) for i in range(len(perm)-1)] if d != 1 else (perm.count(perm[1])-1))
            perm_costs[cst].append(list(perm))

        for costs, perms in perm_costs.items(): # Iterate through the cached results to find the maximum cost
            for perm in perms:
                new_cost = sum([abs(perm[i] - perm[i+1]) if (perms.index(perm) + 1 < len(perms)) else (perm.count(perm[1])-1)] for i in range(len(perm)-1)) // d
                if new_cost > max_cost:
                    max_cost = new_cost
                    max_perm = perm
                    max_d = d

    return max_d, max_perm

import itertools as itt
from functools import reduce

def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return abs(a)

def extend_gap(gap, size, base=1):
    values = []
    for i in range(size):
        nextVal = (base + gap * i) % 2 * itt.accumulate([1] + values, lambda x, y: x * y)[-1]
        while len(values) + 1 < size and nextVal <= i:
            values.append(nextVal)
            base += gap
        values.append(nextVal)
    return values

def is_valid(permutation, d):
    for i in range(len(permutation) - 1):
        if gcd(permutation[i + 1] - permutation[i], d) > 1:
            return False
    return True

def solve():
    max_d = int(input("Enter the maximum value for 'd': "))
    max_size = int(input("Enter the maximum size of permutations:"))

    max_cost, result_permutation = 0, []

    for d in range(1, max_d + 1):
        all_perms = [extend_gap(d, i+1) for i in range(max_size)]
        for permutation in itt.product(*all_perms):
            if is_valid(permutation, d):
                cost = sum([abs(p) for p in permutation])
                if cost > max_cost:
                    result_permutation = list(permutation)
                    max_cost = cost

    print("Maximum Cost:", max_cost, "with Permutation", result_permutation)

import sys

def factorize(n):
    i = 2
    factors = {}
    while True:
        if n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n //= i
        elif n > i*i:
            i += 1
        else:
            break
    return factors

def print_result(maxPermutation):
    print("Max Permutation:", [keys[0] for keys in maxPermutation])
    maxCost = max([val for tup in maxPermutation for val in tup])
    print(f"Max Cost: {maxCost}")

def solve():
    data = {}
    max_permutation = []

    maxN = 10**5 + 1 # Max N value considering user's constraint (2 ≤ n ≤ 2 × 10^5)

    for i, f in enumerate(factorize(i).items()):
        factor, power = f
        if factor not in data:
            data[factor] = [[power,i]]
        else:
            data[factor].append([power,i])

    for fackey in sorted(data.keys(), reverse=True): # Sort the factors in descending order
        for combos in itertools.combinations_with_replacement(range(1, maxN), len(data[fackey])):
            cost = sum([combos[i]*j for i, j in data[fackey]])
            if cost <= maxN and (cost, tuple(combos)) not in max_permutation:  # Ensure max_permutation is unique for the same cost
                max_permutation.append((data[fackey], cost, tuple(combos)))

    max_permutation = sorted(max_permutation, key=lambda x: -x[1])  # Sort the permutations based on costs in descending order
    print_result(max_permutation)

from sys import stdin, setrecursionlimit
setrecursionlimit(16000) # increases recursion limit to handle more than 16 test cases

def dfs(a):
    if not a:
        return 0

    zero_count = float('inf')  # initialize with infinite value

    for i, row in enumerate(a):
        for j, cell in enumerate(row):
            if cell:
                new_field = [x[:j] + [0 if k == i else k] + x[j+1:] for k in a]
                moves = dfs(new_field)
                zero_count = min(zero_count, moves + 1)

    return zero_count - 1 # subtract one to adjust for the initial grass cell that is being checked

def solve():
    t = int(input())
    for _ in range(t):
        field = [[int(c) for c in input().split()] for _ in range(2)]
        print(dfs(field))

from collections import defaultdict, deque

def get_input():
    tests = int(input())
    test_cases = []
    for _ in range(tests):
        rows = list(map(int, input().split()))
        test_cases.append([rows[1:], rows[:1]])
    return test_cases

def solve(test_cases):
    for t in test_cases:
        a = t[0]
        grid = [[0]*len(a) for _ in range(len(t[1]))]   # Create an empty grid of the same size as input

        def dfs(x, y):
            if not (0 <= x < len(grid) and 0 <= y < len(grid[0])):
                return
            if grid[x][y]:
                return
            grid[x][y] = True
            for dx, dy in ((-1, 0), (0, -1), (1, 0), (0, 1)):
                dfs(x + dx, y + dy)
        for r, c in enumerate(a):
            if c:
                dfs(0,c)
                dfs(r, len(t[1]) - c - 1)

        movements = sum([sum(row) for row in grid]) + 2 * (len(t[1]) + max(a))
        print(movements)

import sys
from functools import lru_cache

def solve():
    data = (tuple(map(int, line.split())) for line in sys.stdin) # This reads input line by line from standard input and yields the data as the number of rows, columns for each scenario
    costs = {}
    @lru_cache(maxsize=None) # Using lru_cache for memoization
    def get_cost(x, y):
        if (x, y) == (1, 1):
            return 0
        cost = float('inf')
        try:
            cost = min(get_cost(x - 1, y) + (x-1)*(len(costs[(x-1, 0):(x-1, len(costs[0])+1)])), get_cost(x, y-1) + y)
        except KeyError:  # In case required cells are not calculated yet or out of range (e.g., when x = 1 and y == 0 in the first iteration)
            pass
        costs[(x, y)] = cost
        return cost

    for n_rows, n_cols in data:
        print(get_cost(n_rows, n_cols))

import heapq
import sys

def dijkstra(graph, start):
    pq = [(0, start)]
    dist_dict = {start: 0}
    prev_dict = {start: None}

    while pq:
        cur_vertex, dist_cur = heapq.heappop(pq)

        if cur_vertex not in dist_dict:
            continue

        for neigh_vertex, weight in graph[cur_vertex]:
            distance = dist_cur + weight

            if neigh_vertex not in dist_dict or distance < dist_dict[neigh_vertex]:
                heapq.heappush(pq, (distance, neigh_vertex))
                dist_dict[neigh_vertex] = distance
                prev_dict[neigh_vertex] = cur_vertex

    return dist_dict, prev_dict

def solve():
    num_tests = int(input())

    for _ in range(num_tests):
        n, m = map(int, input().split())

        if not (1 <= n and n <= 20) or not (1 <= m and m <= 20):
            print("Error: Input dimensions should be between 1 and 20.")
            continue

        graph = {k: [] for k in range(1, n*m+1)}
        edges = int(input())

        for _ in range(edges):
            u, v, w = map(int, input().split())
            graph[u].append((v, w))
            graph[v].append((u, w))

        start_vertex = 1
        dist_dict, _ = dijkstra(graph, start_vertex)

        # Ensure optimality or provide an explanation for potential non-optimality
        print("Optimal solution may not be guaranteed due to the nature of Dijkstra's algorithm.")
        min_dist = dist_dict[(m*n)+1]  # Cell (n, m) is at index (m*n)+1 in our representation
        print(f"Minimum cost from cell (1, 1) to cell ({m}, {n}): {min_dist}")

