import heapq

def min_cost(n, m, visited_DFS, visited_BFS, depth_DFS, depth_BFS):
    if (n, m) in visited_DFS or (n, m) in visited_BFS:
        return visited_DFS[(n, m)] if visited_DFS[(n, m)] else visited_BFS[(n, m)]

    minimum_cost = min(min_cost(n+1, m, visited_DFS, visited_BFS, depth_DFS, depth_BFS),
                       min_cost(n, m+1, visited_DFS, visited_BFS, depth_DFS, depth_BFS)) + 1
    if not (n, m) in visited_DFS:
        heapq.heappush(depth_DFS, (-minimum_cost, n, m))
        visited_DFS[(n, m)] = minimum_cost

    if not (n, m) in visited_BFS:
        heapq.heappush(depth_BFS, (minimum_cost, n, m))
        visited_BFS[(n, m)] = minimum_cost

    return minimum_cost

def minPathCostDFS(n, m):
    if n == 1 or m == 1:
        return 1

    visited_DFS = {}
    depth_DFS = []

    print("Minimum DFS Path Cost:", min_cost(1, 1, visited_DFS, {}, [(-n, -m)], set()))
    return min_cost(1, 1, visited_DFS, {}, [(-n, -m)], set())

def minPathCostBFS(n, m):
    if n == 1 or m == 1:
        return 1

    visited_BFS = {}
    depth_BFS = []

    print("Minimum BFS Path Cost:", ' '.join(map(str, heapq.heappop(depth_BFS))))
    return ' '.join(map(str, heapq.heappop(depth_BFS)))

def solve():
    T = int(input().strip())

    for _ in range(T):
        n, m = map(int, input().split())
        print("DFS: ", minPathCostDFS(n, m))
        print("BFS: ", minPathCostBFS(n, m))
